window.ATLAS_PRIORITY_DETAILS=window.ATLAS_PRIORITY_DETAILS||{};window.ATLAS_PRIORITY_DETAILS["evidence-001"]={"TSPYL6":{"coreEvidence":[{"partner":"ZMYM2","hgnc":"HGNC:12989","core":true,"core_annotation":{"hgnc":"HGNC:12989","symbol_at_source":"ZMYM2","accession":"Q9UBW7","function":"Histone modification erase cofactor, TF","target":"DNA","pmids":["12493763"],"complexes":"BHC, LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":243,"hub_weight":0.4130961923860138,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in the negative regulation of transcription","source":"project UniProt records20261017/18"},{"partner":"ZMYM3","hgnc":"HGNC:13054","core":true,"core_annotation":{"hgnc":"HGNC:13054","symbol_at_source":"ZMYM3","accession":"Q14202","function":"Histone modification erase cofactor","target":"DNA","pmids":["12493763"],"complexes":"BHC","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":127,"hub_weight":0.5314940034527339,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for regulation of cell morphology and cytoskeletal organization","source":"project UniProt records20261017/18"},{"partner":"KDM5B","hgnc":"HGNC:18039","core":true,"core_annotation":{"hgnc":"HGNC:18039","symbol_at_source":"KDM5B","accession":"Q9UGL1","function":"Histone modification erase","target":"histone","pmids":["17363312"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":95,"hub_weight":0.5872202195147035,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone demethylase that demethylates 'Lys-4' of histone H3, thereby playing a central role in histone code (PubMed:24952722, PubMed:27214403, PubMed:28262558). Does not demethylate histone H3 'Lys-9' or H3 'Lys-27'. Demethylates trimethylated, dimethylated and monomethylated H3 'Lys-4'. Acts as a transcriptional corepressor for FOXG1B and PAX9. Favors the proliferation of breast cancer cells by repressing tumor suppressor genes such as BRCA1 and HOXA5 (PubMed:24952722). In contrast, may act as a tumor suppressor for melanoma. Represses the CLOCK-BMAL1 heterodimer-mediated transcriptional activation of the core clock component PER2 (By similarity)","source":"project UniProt records20261017/18"},{"partner":"USP46","hgnc":"HGNC:20075","core":true,"core_annotation":{"hgnc":"HGNC:20075","symbol_at_source":"USP46","accession":"P62068","function":"Histone modification erase","target":"histone","pmids":["22033037"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":60,"hub_weight":0.674199862463242,"quality":0.65,"programmes":["BioPlex","pubmed:40205054"],"pmids":["28514442","33961781","40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Deubiquitinating enzyme that plays a role in behavior, possibly by regulating GABA action. May act by mediating the deubiquitination of GAD1/GAD67 (By similarity). Has almost no deubiquitinating activity by itself and requires the interaction with WDR48 to have a high activity (PubMed:19075014, PubMed:26388029). Not involved in deubiquitination of monoubiquitinated FANCD2 (PubMed:19075014)","source":"project UniProt records20261017/18"},{"partner":"USP12","hgnc":"HGNC:20485","core":true,"core_annotation":{"hgnc":"HGNC:20485","symbol_at_source":"USP12","accession":"O75317","function":"Histone modification erase","target":"histone","pmids":["22033037"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":57,"hub_weight":0.6835859270246633,"quality":0.65,"programmes":["BioPlex","pubmed:40205054"],"pmids":["28514442","33961781","40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm; Cell membrane","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Deubiquitinating enzyme that plays various roles in the regulation of the immune response and inflammation (PubMed:19075014, PubMed:27373336). During TCR engagement and activation, translocates into the cytoplasm and deubiquitinates its substrates LAT and TRAT1 and prevents their lysosome-dependent degradation to stabilize the TCR signaling complex at the plasma membrane (PubMed:26811477). Plays an essential role in the selective LPS-induced macrophage response through the activation of NF-kappa-B pathway (PubMed:28063927). In addition, promotes that antiviral immune response through targeting DNA sensor IFI16 to inhibit its proteasome-dependent degradation (PubMed:37410794). Participates in the interferon signaling pathway and antiviral response independently of its deubiquitinase activity by maintaining nuclear phosphorylated STAT1 levels via inhibition of its CREBBP-mediated acetylation and subsequent dephosphorylation (PubMed:31899788). Plays an intrinsic role in promoting the differentiation, activation and proliferation of CD4(+) T-cell by activating the NF-kappa-B signaling pathway through deubiquitinating and stabilizing B-cell lymphoma/leukemia 10/BCL10 (By similarity). In myeloid-derived suppressor cells promotes the activation of the NF-kappa-B via deubiquitination and stabilization of RELA (By similarity). Regulates the 'Lys-63'-linked polyubiquitin chains of BAX and thereby modulates the mitochondrial apoptotic process (PubMed:36361894). Negative regulator of NOTCH signaling that specifically deubiquitinates non-activated NOTCH receptors to target them for lysosomal degradation; deubiquitination of NOTCH stimulates its transport form late endosomes to lysosomes (PubMed:22778262). Protects neurons against HTT/huntingtin-induced polyglutamine expansion-dependent neurodegeneration through regulation of autophagic flux (PubMed:30266909). This function is independent of deubiquitinase activity or of other components of the USP12-WDR20-WDR48 deubiquitinating complex (By similarity). In complex with WDR48, acts as a potential tumor suppressor by positively regulating PHLPP1 stability (PubMed:24145035)\n(Microbial infection) Forms a complex with Epstein-Barr virus protein EBNA3 which is an active deubiquitinase activity that may select specific substrates to promote B-lymphocyte transformation","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"TSPYL1","accession":"Q9H0U9","identity":0.612,"qcov":0.959,"tcov":0.938,"domain_context":"shared_family_context","structure_qualified":"False","function_pmids":[],"function":"","member_mechanism_evidence_available":false}]},"TIGD6":{"coreEvidence":[{"partner":"CHAF1A","hgnc":"HGNC:1910","core":true,"core_annotation":{"hgnc":"HGNC:1910","symbol_at_source":"CHAF1A","accession":"Q13111","function":"Chromatin remodeling","target":"histone","pmids":["7600578"],"complexes":"CAF-1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":190,"hub_weight":0.45643546458763845,"quality":0.65,"programmes":["pubmed:26496610"],"pmids":["26496610"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HeLa epitheloid cervical carcinoma cell\", \"human-hela\"]"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as a component of the histone chaperone complex chromatin assembly factor 1 (CAF-1), which assembles histone octamers onto DNA during replication and repair. CAF-1 performs the first step of the nucleosome assembly process, bringing newly synthesized histones H3 and H4 to replicating DNA; histones H2A/H2B can bind to this chromatin precursor subsequent to DNA replication to complete the histone octamer. It may play a role in heterochromatin maintenance in proliferating cells by bringing newly synthesized cbx proteins to heterochromatic DNA replication foci","source":"project UniProt records20261017/18"},{"partner":"MTA1","hgnc":"HGNC:7410","core":true,"core_annotation":{"hgnc":"HGNC:7410","symbol_at_source":"MTA1","accession":"Q13330","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["9885572"],"complexes":"NuRD","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":292,"hub_weight":0.3823595564509363,"quality":0.65,"programmes":["pubmed:26496610"],"pmids":["26496610"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus; Nucleus envelope; Cytoplasm; Cytoplasm, cytoskeleton","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcriptional coregulator which can act as both a transcriptional corepressor and coactivator (PubMed:16617102, PubMed:17671180, PubMed:17922032, PubMed:21965678, PubMed:24413532). Acts as a component of the histone deacetylase NuRD complex which participates in the remodeling of chromatin (PubMed:16428440, PubMed:28977666). In the NuRD complex, regulates transcription of its targets by modifying the acetylation status of the target chromatin and cofactor accessibility to the target DNA (PubMed:17671180). In conjunction with other components of NuRD, acts as a transcriptional corepressor of BRCA1, ESR1, TFF1 and CDKN1A (PubMed:17922032, PubMed:24413532). Acts as a transcriptional coactivator of BCAS3, and SUMO2, independent of the NuRD complex (PubMed:16617102, PubMed:17671180, PubMed:21965678). Stimulates the expression of WNT1 by inhibiting the expression of its transcriptional corepressor SIX3 (By similarity). Regulates p53-dependent and -independent DNA repair processes following genotoxic stress (PubMed:19837670). Regulates the stability and function of p53/TP53 by inhibiting its ubiquitination by COP1 and MDM2 thereby regulating the p53-dependent DNA repair (PubMed:19837670). Plays a role in the regulation of the circadian clock and is essential for the generation and maintenance of circadian rhythms under constant light and for normal entrainment of behavior to light-dark (LD) cycles (By similarity). Positively regulates the CLOCK-BMAL1 heterodimer mediated transcriptional activation of its own transcription and the transcription of CRY1 (By similarity). Regulates deacetylation of BMAL1 by regulating SIRT1 expression, resulting in derepressing CRY1-mediated transcription repression (By similarity). With TFCP2L1, promotes establishment and maintenance of pluripotency in embryonic stem cells (ESCs) and inhibits endoderm differentiation (By similarity)\nBinds to ESR1 and sequesters it in the cytoplasm and enhances its non-genomic responses","source":"project UniProt records20261017/18"},{"partner":"HDGFL2","hgnc":"HGNC:14680","core":true,"core_annotation":{"hgnc":"HGNC:14680","symbol_at_source":"HDGFL2","accession":"Q7Z4V5","function":"Histone modification read","target":"histone","pmids":["217205545"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":179,"hub_weight":0.46726931351599776,"quality":0.65,"programmes":["pubmed:26496610"],"pmids":["26496610"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HeLa epitheloid cervical carcinoma cell\", \"human-hela\"]"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as an epigenetic regulator of myogenesis in cooperation with DPF3a (isoform 2 of DPF3/BAF45C) (PubMed:32459350). Associates with the BAF complex via its interaction with DPF3a and HDGFL2-DPF3a activate myogenic genes by increasing chromatin accessibility through recruitment of SMARCA4/BRG1/BAF190A (ATPase subunit of the BAF complex) to myogenic gene promoters (PubMed:32459350). Promotes the repair of DNA double-strand breaks (DSBs) through the homologous recombination pathway by facilitating the recruitment of the DNA endonuclease RBBP8 to the DSBs (PubMed:26721387). Preferentially binds to chromatin regions marked by H3K9me3, H3K27me3 and H3K36me2 (PubMed:26721387, PubMed:32459350). Involved in cellular growth control, through the regulation of cyclin D1 expression (PubMed:25689719)","source":"project UniProt records20261017/18"},{"partner":"SS18L2","hgnc":"HGNC:15593","core":true,"core_annotation":{"hgnc":"HGNC:15593","symbol_at_source":"SS18L2","accession":"Q9UHA2","function":"Chromatin remodeling","target":"chromatin","pmids":["19163965","8666667"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":62,"hub_weight":0.6681531047810609,"quality":0.65,"programmes":["pubmed:26496610"],"pmids":["26496610"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HeLa epitheloid cervical carcinoma cell\", \"human-hela\"]"],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"RSRC2":{"coreEvidence":[{"partner":"BRD3","hgnc":"HGNC:1104","core":true,"core_annotation":{"hgnc":"HGNC:1104","symbol_at_source":"BRD3","accession":"Q15059","function":"Histone modification read","target":"histone","pmids":["18406326"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":446,"hub_weight":0.31750031750047625,"quality":0.65,"programmes":["pubmed:31753913"],"pmids":["31753913"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromatin reader that recognizes and binds acetylated histones, thereby controlling gene expression and remodeling chromatin structures (PubMed:18406326, PubMed:22464331, PubMed:27105114, PubMed:32895492). Recruits transcription factors and coactivators to target gene sites, and activates RNA polymerase II machinery for transcriptional elongation (PubMed:29567837, PubMed:32895492). In vitro, binds acetylated lysine residues on the N-terminus of histone H2A, H2B, H3 and H4 (PubMed:18406326). Involved in endoderm differentiation via its association with long non-coding RNA (lncRNA) DIGIT: BRD3 undergoes liquid-liquid phase separation upon binding to lncRNA DIGIT, promoting binding to histone H3 acetylated at 'Lys-18' (H3K18ac) to induce endoderm gene expression (PubMed:32895492). Also binds non-histones acetylated proteins, such as GATA1 and GATA2: regulates transcription by promoting the binding of the transcription factor GATA1 to its targets (By similarity)","source":"project UniProt records20261017/18"},{"partner":"H2BC8","hgnc":"HGNC:4746","core":true,"core_annotation":{"hgnc":"HGNC:4746","symbol_at_source":"HIST1H2BG","accession":"P62807","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":546,"hub_weight":0.28964222318174615,"quality":0.4,"programmes":["pubmed:25281560"],"pmids":["25281560"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling\nHas broad antibacterial activity. May contribute to the formation of the functional antimicrobial barrier of the colonic epithelium, and to the bactericidal activity of amniotic fluid","source":"project UniProt records20261017/18"},{"partner":"MECP2","hgnc":"HGNC:6990","core":true,"core_annotation":{"hgnc":"HGNC:6990","symbol_at_source":"MECP2","accession":"P51608","function":"Histone modification write cofactor, Histone modification write cofactor, TF","target":"DNA","pmids":["10773092"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1032,"hub_weight":0.2149667901961739,"quality":0.65,"programmes":["pubmed:38697112"],"pmids":["38697112"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Chromosomal protein that binds to methylated DNA. It can bind specifically to a single methyl-CpG pair. It is not influenced by sequences flanking the methyl-CpGs. Mediates transcriptional repression through interaction with histone deacetylase and the corepressor SIN3A. Binds both 5-methylcytosine (5mC) and 5-hydroxymethylcytosine (5hmC)-containing DNA, with a preference for 5-methylcytosine (5mC)","source":"project UniProt records20261017/18"},{"partner":"OGT","hgnc":"HGNC:8127","core":true,"core_annotation":{"hgnc":"HGNC:8127","symbol_at_source":"OGT","accession":"O15294","function":"Histone modification write","target":"histone","pmids":["22121020"],"complexes":"NSL","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":741,"hub_weight":0.2514182275771345,"quality":1,"programmes":["pubmed:32994395"],"pmids":["32994395"],"assays":["reconstituted"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Mitochondrion; Membrane; Cytoplasm; Nucleus; Cell membrane; Mitochondrion membrane; Cell projection; Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalyzes the transfer of a single N-acetylglucosamine from UDP-GlcNAc to a serine or threonine residue in cytoplasmic and nuclear proteins resulting in their modification with a beta-linked N-acetylglucosamine (O-GlcNAc) (PubMed:12150998, PubMed:15361863, PubMed:19451179, PubMed:20018868, PubMed:21240259, PubMed:21285374, PubMed:23103939, PubMed:26237509, PubMed:26369908, PubMed:26678539, PubMed:27713473, PubMed:37541260, PubMed:37962578). Glycosylates a large and diverse number of proteins including histone H2B, AKT1, AMPK, ATG4B, CAPRIN1, EZH2, FNIP1, GSDMD, KRT7, LMNA, LMNB1, LMNB2, RPTOR, HOXA1, PFKL, KMT2E/MLL5, MAPT/TAU, TET2, RBL2, RET, NOD2 and HCFC1 (PubMed:19451179, PubMed:20200153, PubMed:21285374, PubMed:22923583, PubMed:23353889, PubMed:24474760, PubMed:26237509, PubMed:26369908, PubMed:26678539, PubMed:27527864, PubMed:30699359, PubMed:34074792, PubMed:34667079, PubMed:37541260, PubMed:37962578). Can regulate their cellular processes via cross-talk between glycosylation and phosphorylation or by affecting proteolytic processing (PubMed:21285374). Involved in insulin resistance in muscle and adipocyte cells via glycosylating insulin signaling components and inhibiting the 'Thr-308' phosphorylation of AKT1, enhancing IRS1 phosphorylation and attenuating insulin signaling (By similarity). Involved in glycolysis regulation by mediating glycosylation of 6-phosphofructokinase PFKL, inhibiting its activity (PubMed:22923583). Plays a key role in chromatin structure by mediating O-GlcNAcylation of 'Ser-112' of histone H2B: recruited to CpG-rich transcription start sites of active genes via its interaction with TET proteins (TET1, TET2 or TET3) (PubMed:22121020, PubMed:23353889). As part of the NSL complex indirectly involved in acetylation of nucleosomal histone H4 on several lysine residues (PubMed:20018852). O-GlcNAcylation of 'Ser-75' of EZH2 increases its stability, and facilitating the formation of H3K27me3 by the PRC2/EED-EZH2 complex (PubMed:24474760). Stabilizes KMT2E/MLL5 by mediating its glycosylation, thereby preventing KMT2E/MLL5 ubiquitination (PubMed:26678539). Regulates circadian oscillation of the clock genes and glucose homeostasis in the liver (By similarity). Stabilizes clock proteins BMAL1 and CLOCK through O-glycosylation, which prevents their ubiquitination and subsequent degradation (By similarity). Promotes the CLOCK-BMAL1-mediated transcription of genes in the negative loop of the circadian clock such as PER1/2 and CRY1/2. O-glycosylates HCFC1 and regulates its proteolytic processing and transcriptional activity (PubMed:21285374, PubMed:28302723, PubMed:28584052). Component of a THAP1/THAP3-HCFC1-OGT complex that is required for the regulation of the transcriptional activity of RRM1 (PubMed:20200153). Regulates mitochondrial motility in neurons by mediating glycosylation of TRAK1 (By similarity). Promotes autophagy by mediating O-glycosylation of ATG4B (PubMed:27527864). Acts as a regulator of mTORC1 signaling by mediating O-glycosylation of RPTOR and FNIP1: O-GlcNAcylation of RPTOR in response to glucose sufficiency promotes activation of the mTORC1 complex (PubMed:30699359, PubMed:37541260)\nThe mitochondrial isoform (mOGT) is cytotoxic and triggers apoptosis in several cell types including INS1, an insulinoma cell line\nHas N-acetylglucosaminyltransferase activity: glycosylates proteins, such as HNRNPU, NEUROD1, NUP62 and PDCD6IP (PubMed:31527085). Displays specific substrate selectivity compared to other isoforms (PubMed:31527085)","source":"project UniProt records20261017/18"},{"partner":"AURKA","hgnc":"HGNC:11393","core":true,"core_annotation":{"hgnc":"HGNC:11393","symbol_at_source":"AURKA","accession":"O14965","function":"Histone modification write","target":"histone","pmids":["12576638"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":603,"hub_weight":0.27671226645624275,"quality":0.65,"programmes":["pubmed:32989298"],"pmids":["32989298"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole; Cell projection, neuron projection; Cell projection, cilium; Cytoplasm, cytoskeleton, cilium basal body; Basolateral cell membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Mitotic serine/threonine kinase that contributes to the regulation of cell cycle progression (PubMed:11039908, PubMed:12390251, PubMed:17125279, PubMed:17360485, PubMed:18615013, PubMed:26246606). Associates with the centrosome and the spindle microtubules during mitosis and plays a critical role in various mitotic events including the establishment of mitotic spindle, centrosome duplication, centrosome separation as well as maturation, chromosomal alignment, spindle assembly checkpoint, and cytokinesis (PubMed:14523000, PubMed:26246606). Required for normal spindle positioning during mitosis and for the localization of NUMA1 and DCTN1 to the cell cortex during metaphase (PubMed:27335426). Required for initial activation of CDK1 at centrosomes (PubMed:13678582, PubMed:15128871). Phosphorylates numerous target proteins, including ARHGEF2, BORA, BRCA1, CDC25B, DLGP5, HDAC6, KIF2A, LATS2, NDEL1, PARD3, PPP1R2, PLK1, RASSF1, TACC3, p53/TP53 and TPX2 (PubMed:11551964, PubMed:14702041, PubMed:15128871, PubMed:15147269, PubMed:15987997, PubMed:17604723, PubMed:18056443, PubMed:18615013). Phosphorylates MCRS1 which is required for MCRS1-mediated kinetochore fiber assembly and mitotic progression (PubMed:27192185). Regulates KIF2A tubulin depolymerase activity (PubMed:19351716). Important for microtubule formation and/or stabilization (PubMed:18056443). Required for normal axon formation (PubMed:19812038). Plays a role in microtubule remodeling during neurite extension (PubMed:19668197). Also acts as a key regulatory component of the p53/TP53 pathway, and particularly the checkpoint-response pathways critical for oncogenic transformation of cells, by phosphorylating and destabilizing p53/TP53 (PubMed:14702041). Phosphorylates its own inhibitors, the protein phosphatase type 1 (PP1) isoforms, to inhibit their activity (PubMed:11551964). Inhibits cilia outgrowth (By similarity). Required for cilia disassembly via phosphorylation of HDAC6 and subsequent deacetylation of alpha-tubulin (PubMed:17604723, PubMed:20643351). Regulates protein levels of the anti-apoptosis protein BIRC5 by suppressing the expression of the SCF(FBXL7) E3 ubiquitin-protein ligase substrate adapter FBXL7 through the phosphorylation of the transcription factor FOXP1 (PubMed:28218735)","source":"project UniProt records20261017/18"},{"partner":"UBE2H","hgnc":"HGNC:12484","core":true,"core_annotation":{"hgnc":"HGNC:12484","symbol_at_source":"UBE2H","accession":"P62256","function":"Histone modification write","target":"histone","pmids":["8132613"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1345,"hub_weight":0.18932061141568826,"quality":0.65,"programmes":["pubmed:38113892"],"pmids":["38113892"],"assays":["capture_association"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Accepts ubiquitin from the E1 complex and catalyzes its covalent attachment to other proteins (PubMed:17588522, PubMed:20061386, PubMed:8132613). E2 ubiquitin conjugating enzyme that transfers ubiquitin to MAEA, a core component of the CTLH E3 ubiquitin-protein ligase complex (PubMed:29911972). In vitro catalyzes 'Lys-11'- and 'Lys-48'-linked polyubiquitination (PubMed:20061386). Capable, in vitro, to ubiquitinate histone H2A (PubMed:8132613)","source":"project UniProt records20261017/18"},{"partner":"JMJD6","hgnc":"HGNC:19355","core":true,"core_annotation":{"hgnc":"HGNC:19355","symbol_at_source":"JMJD6","accession":"Q6NYC1","function":"Histone modification erase","target":"histone","pmids":["17947579"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":197,"hub_weight":0.44992127066584753,"quality":0.65,"programmes":["BioPlex","pubmed:21555454"],"pmids":["21555454","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HCT116","dataset_cell:HEK293T"],"partner_location":"Nucleus, nucleoplasm; Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Dioxygenase that can both act as a arginine demethylase and a lysyl-hydroxylase (PubMed:17947579, PubMed:20684070, PubMed:21060799, PubMed:22189873, PubMed:24498420). Acts as a lysyl-hydroxylase that catalyzes 5-hydroxylation on specific lysine residues of target proteins such as U2AF2/U2AF65 and LUC7L2. Regulates RNA splicing by mediating 5-hydroxylation of U2AF2/U2AF65, affecting the pre-mRNA splicing activity of U2AF2/U2AF65 (PubMed:19574390). Hydroxylates its own N-terminus, which is required for homooligomerization (PubMed:22189873). Plays a role in the regulation of nucleolar liquid-liquid phase separation (LLPS) by post-translationally modifying LIAT1 at its lysine-rich domain which inhibits LIAT1 nucleolar targeting (By similarity). In addition to peptidyl-lysine 5-dioxygenase activity, may act as an RNA hydroxylase, as suggested by its ability to bind single strand RNA (PubMed:20679243, PubMed:29176719). Also acts as an arginine demethylase which preferentially demethylates asymmetric dimethylation (PubMed:17947579, PubMed:24360279, PubMed:24498420). Demethylates histone H3 at 'Arg-2' (H3R2me) and histone H4 at 'Arg-3' (H4R3me), including mono-, symmetric di- and asymmetric dimethylated forms, thereby playing a role in histone code (PubMed:17947579, PubMed:24360279). However, histone arginine demethylation may not constitute the primary activity in vivo (PubMed:17947579, PubMed:21060799, PubMed:22189873). In collaboration with BRD4, interacts with the positive transcription elongation factor b (P-TEFb) complex in its active form to regulate polymerase II promoter-proximal pause release for transcriptional activation of a large cohort of genes. On distal enhancers, so called anti-pause enhancers, demethylates both histone H4R3me2 and the methyl cap of 7SKsnRNA leading to the dismissal of the 7SKsnRNA:HEXIM1 inhibitor complex. After removal of repressive marks, the complex BRD4:JMJD6 attract and retain the P-TEFb complex on chromatin, leading to its activation, promoter-proximal polymerase II pause release, and transcriptional activation (PubMed:24360279). Demethylates other arginine methylated-proteins such as ESR1 (PubMed:24498420). Has no histone lysine demethylase activity (PubMed:21060799). Required for differentiation of multiple organs during embryogenesis. Acts as a key regulator of hematopoietic differentiation: required for angiogenic sprouting by regulating the pre-mRNA splicing activity of U2AF2/U2AF65 (By similarity). Seems to be necessary for the regulation of macrophage cytokine responses (PubMed:15622002)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"TSTD2":{"coreEvidence":[{"partner":"BUB1","hgnc":"HGNC:1148","core":true,"core_annotation":{"hgnc":"HGNC:1148","symbol_at_source":"BUB1","accession":"O43683","function":"Histone modification write","target":"histone","pmids":["20929775"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":105,"hub_weight":0.5679618342470648,"quality":0.75,"programmes":["pubmed:24412244"],"pmids":["24412244"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome, centromere, kinetochore","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine-protein kinase that performs 2 crucial functions during mitosis: it is essential for spindle-assembly checkpoint signaling and for correct chromosome alignment. Has a key role in the assembly of checkpoint proteins at the kinetochore, being required for the subsequent localization of CENPF, BUB1B, CENPE and MAD2L1. Required for the kinetochore localization of PLK1. Required for centromeric enrichment of AUKRB in prometaphase. Plays an important role in defining SGO1 localization and thereby affects sister chromatid cohesion. Promotes the centromeric localization of TOP2A (PubMed:35044816). Acts as a substrate for anaphase-promoting complex or cyclosome (APC/C) in complex with its activator CDH1 (APC/C-Cdh1). Necessary for ensuring proper chromosome segregation and binding to BUB3 is essential for this function. Can regulate chromosome segregation in a kinetochore-independent manner. Can phosphorylate BUB3. The BUB1-BUB3 complex plays a role in the inhibition of APC/C when spindle-assembly checkpoint is activated and inhibits the ubiquitin ligase activity of APC/C by phosphorylating its activator CDC20. This complex can also phosphorylate MAD1L1. Kinase activity is essential for inhibition of APC/CCDC20 and for chromosome alignment but does not play a major role in the spindle-assembly checkpoint activity. Mediates cell death in response to chromosome missegregation and acts to suppress spontaneous tumorigenesis","source":"project UniProt records20261017/18"},{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:35563538"],"pmids":["35563538"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"AURKA","hgnc":"HGNC:11393","core":true,"core_annotation":{"hgnc":"HGNC:11393","symbol_at_source":"AURKA","accession":"O14965","function":"Histone modification write","target":"histone","pmids":["12576638"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":603,"hub_weight":0.27671226645624275,"quality":0.75,"programmes":["pubmed:24412244"],"pmids":["24412244"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole; Cell projection, neuron projection; Cell projection, cilium; Cytoplasm, cytoskeleton, cilium basal body; Basolateral cell membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Mitotic serine/threonine kinase that contributes to the regulation of cell cycle progression (PubMed:11039908, PubMed:12390251, PubMed:17125279, PubMed:17360485, PubMed:18615013, PubMed:26246606). Associates with the centrosome and the spindle microtubules during mitosis and plays a critical role in various mitotic events including the establishment of mitotic spindle, centrosome duplication, centrosome separation as well as maturation, chromosomal alignment, spindle assembly checkpoint, and cytokinesis (PubMed:14523000, PubMed:26246606). Required for normal spindle positioning during mitosis and for the localization of NUMA1 and DCTN1 to the cell cortex during metaphase (PubMed:27335426). Required for initial activation of CDK1 at centrosomes (PubMed:13678582, PubMed:15128871). Phosphorylates numerous target proteins, including ARHGEF2, BORA, BRCA1, CDC25B, DLGP5, HDAC6, KIF2A, LATS2, NDEL1, PARD3, PPP1R2, PLK1, RASSF1, TACC3, p53/TP53 and TPX2 (PubMed:11551964, PubMed:14702041, PubMed:15128871, PubMed:15147269, PubMed:15987997, PubMed:17604723, PubMed:18056443, PubMed:18615013). Phosphorylates MCRS1 which is required for MCRS1-mediated kinetochore fiber assembly and mitotic progression (PubMed:27192185). Regulates KIF2A tubulin depolymerase activity (PubMed:19351716). Important for microtubule formation and/or stabilization (PubMed:18056443). Required for normal axon formation (PubMed:19812038). Plays a role in microtubule remodeling during neurite extension (PubMed:19668197). Also acts as a key regulatory component of the p53/TP53 pathway, and particularly the checkpoint-response pathways critical for oncogenic transformation of cells, by phosphorylating and destabilizing p53/TP53 (PubMed:14702041). Phosphorylates its own inhibitors, the protein phosphatase type 1 (PP1) isoforms, to inhibit their activity (PubMed:11551964). Inhibits cilia outgrowth (By similarity). Required for cilia disassembly via phosphorylation of HDAC6 and subsequent deacetylation of alpha-tubulin (PubMed:17604723, PubMed:20643351). Regulates protein levels of the anti-apoptosis protein BIRC5 by suppressing the expression of the SCF(FBXL7) E3 ubiquitin-protein ligase substrate adapter FBXL7 through the phosphorylation of the transcription factor FOXP1 (PubMed:28218735)","source":"project UniProt records20261017/18"},{"partner":"IKZF1","hgnc":"HGNC:13176","core":true,"core_annotation":{"hgnc":"HGNC:13176","symbol_at_source":"IKZF1","accession":"Q13422","function":"Chromatin remodeling, TF","target":"DNA","pmids":["19141594"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":251,"hub_weight":0.4075695729696112,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcription regulator of hematopoietic cell differentiation (PubMed:17934067). Binds gamma-satellite DNA (PubMed:17135265, PubMed:19141594). Plays a role in the development of lymphocytes, B- and T-cells. Binds and activates the enhancer (delta-A element) of the CD3-delta gene. Repressor of the TDT (fikzfterminal deoxynucleotidyltransferase) gene during thymocyte differentiation. Regulates transcription through association with both HDAC-dependent and HDAC-independent complexes. Targets the 2 chromatin-remodeling complexes, NuRD and BAF (SWI/SNF), in a single complex (PYR complex), to the beta-globin locus in adult erythrocytes (PubMed:10204490). Increases normal apoptosis in adult erythroid cells (By similarity). Confers early temporal competence to retinal progenitor cells (RPCs) (By similarity). Function is isoform-specific and is modulated by dominant-negative inactive isoforms (PubMed:17135265, PubMed:17934067). Recognized by CRBN and is targeted for degradation by DCX (DDB1-CUL4-X-box) E3 protein ligase complex (PubMed:41565821)","source":"project UniProt records20261017/18"},{"partner":"L3MBTL3","hgnc":"HGNC:23035","core":true,"core_annotation":{"hgnc":"HGNC:23035","symbol_at_source":"L3MBTL3","accession":"Q96JM7","function":"Histone modification read","target":"histone","pmids":["23292653"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":112,"hub_weight":0.5555555555555556,"quality":0.75,"programmes":["pubmed:26871637"],"pmids":["26871637"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Is a negative regulator of Notch target genes expression, required for RBPJ-mediated transcriptional repression (PubMed:29030483). It recruits KDM1A to Notch-responsive elements and promotes KDM1A-mediated H3K4me demethylation (PubMed:29030483). Involved in the regulation of ubiquitin-dependent degradation of a set of methylated non-histone proteins, including SOX2, DNMT1 and E2F1. It acts as an adapter recruiting the CRL4-DCAF5 E3 ubiquitin ligase complex to methylated target proteins (PubMed:29691401, PubMed:30442713). Required for normal maturation of myeloid progenitor cells (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"FAM131B":{"coreEvidence":[{"partner":"CDC6","hgnc":"HGNC:1744","core":true,"core_annotation":{"hgnc":"HGNC:1744","symbol_at_source":"CDC6","accession":"Q99741","function":"Chromatin remodeling","target":"chromatin","pmids":["22358331"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":86,"hub_weight":0.6063390625908325,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in the initiation of DNA replication. Also participates in checkpoint controls that ensure DNA replication is completed before mitosis is initiated","source":"project UniProt records20261017/18"},{"partner":"NCOA1","hgnc":"HGNC:7668","core":true,"core_annotation":{"hgnc":"HGNC:7668","symbol_at_source":"NCOA1","accession":"Q15788","function":"Histone modification write","target":"histone","pmids":["9296499"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":131,"hub_weight":0.5255883312276367,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Nuclear receptor coactivator that directly binds nuclear receptors and stimulates the transcriptional activities in a hormone-dependent fashion. Involved in the coactivation of different nuclear receptors, such as for steroids (PGR, GR and ER), retinoids (RXRs), thyroid hormone (TRs) and prostanoids (PPARs). Also involved in coactivation mediated by STAT3, STAT5A, STAT5B and STAT6 transcription factors. Displays histone acetyltransferase activity toward H3 and H4; the relevance of such activity remains however unclear. Plays a central role in creating multisubunit coactivator complexes that act via remodeling of chromatin, and possibly acts by participating in both chromatin remodeling and recruitment of general transcription factors. Required with NCOA2 to control energy balance between white and brown adipose tissues. Required for mediating steroid hormone response. Isoform 2 has a higher thyroid hormone-dependent transactivation activity than isoform 1 and isoform 3","source":"project UniProt records20261017/18"},{"partner":"AURKA","hgnc":"HGNC:11393","core":true,"core_annotation":{"hgnc":"HGNC:11393","symbol_at_source":"AURKA","accession":"O14965","function":"Histone modification write","target":"histone","pmids":["12576638"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":603,"hub_weight":0.27671226645624275,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole; Cell projection, neuron projection; Cell projection, cilium; Cytoplasm, cytoskeleton, cilium basal body; Basolateral cell membrane","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Mitotic serine/threonine kinase that contributes to the regulation of cell cycle progression (PubMed:11039908, PubMed:12390251, PubMed:17125279, PubMed:17360485, PubMed:18615013, PubMed:26246606). Associates with the centrosome and the spindle microtubules during mitosis and plays a critical role in various mitotic events including the establishment of mitotic spindle, centrosome duplication, centrosome separation as well as maturation, chromosomal alignment, spindle assembly checkpoint, and cytokinesis (PubMed:14523000, PubMed:26246606). Required for normal spindle positioning during mitosis and for the localization of NUMA1 and DCTN1 to the cell cortex during metaphase (PubMed:27335426). Required for initial activation of CDK1 at centrosomes (PubMed:13678582, PubMed:15128871). Phosphorylates numerous target proteins, including ARHGEF2, BORA, BRCA1, CDC25B, DLGP5, HDAC6, KIF2A, LATS2, NDEL1, PARD3, PPP1R2, PLK1, RASSF1, TACC3, p53/TP53 and TPX2 (PubMed:11551964, PubMed:14702041, PubMed:15128871, PubMed:15147269, PubMed:15987997, PubMed:17604723, PubMed:18056443, PubMed:18615013). Phosphorylates MCRS1 which is required for MCRS1-mediated kinetochore fiber assembly and mitotic progression (PubMed:27192185). Regulates KIF2A tubulin depolymerase activity (PubMed:19351716). Important for microtubule formation and/or stabilization (PubMed:18056443). Required for normal axon formation (PubMed:19812038). Plays a role in microtubule remodeling during neurite extension (PubMed:19668197). Also acts as a key regulatory component of the p53/TP53 pathway, and particularly the checkpoint-response pathways critical for oncogenic transformation of cells, by phosphorylating and destabilizing p53/TP53 (PubMed:14702041). Phosphorylates its own inhibitors, the protein phosphatase type 1 (PP1) isoforms, to inhibit their activity (PubMed:11551964). Inhibits cilia outgrowth (By similarity). Required for cilia disassembly via phosphorylation of HDAC6 and subsequent deacetylation of alpha-tubulin (PubMed:17604723, PubMed:20643351). Regulates protein levels of the anti-apoptosis protein BIRC5 by suppressing the expression of the SCF(FBXL7) E3 ubiquitin-protein ligase substrate adapter FBXL7 through the phosphorylation of the transcription factor FOXP1 (PubMed:28218735)","source":"project UniProt records20261017/18"},{"partner":"TOP2A","hgnc":"HGNC:11989","core":true,"core_annotation":{"hgnc":"HGNC:11989","symbol_at_source":"TOP2A","accession":"P11388","function":"Chromatin remodeling","target":"DNA","pmids":["11062478"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":461,"hub_weight":0.3128056235449272,"quality":0.65,"programmes":["BioPlex"],"pmids":["28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus, nucleoplasm; Nucleus; Nucleus, nucleolus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Key decatenating enzyme that alters DNA topology by binding to two double-stranded DNA molecules, generating a double-stranded break in one of the strands, passing the intact strand through the broken strand, and religating the broken strand (PubMed:17567603, PubMed:18790802, PubMed:22013166, PubMed:22323612, PubMed:27754753). May play a role in regulating the period length of BMAL1 transcriptional oscillation (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"TMEM35B":{"coreEvidence":[{"partner":"H1-5","hgnc":"HGNC:4719","core":true,"core_annotation":{"hgnc":"HGNC:4719","symbol_at_source":"HIST1H1B","accession":"P16401","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":330,"hub_weight":0.3627381250550058,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","dataset_cell:HCT116"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H1 protein binds to linker DNA between nucleosomes forming the macromolecular structure known as the chromatin fiber (By similarity). Histones H1 are necessary for the condensation of nucleosome chains into higher-order structured fibers and promote formation of the H3K27me3 mark by the PRC2/EED-EZH2 complex (PubMed:40516528). Also acts as a regulator of individual gene transcription through chromatin remodeling, nucleosome spacing and DNA methylation (By similarity)","source":"project UniProt records20261017/18"},{"partner":"H2AC20","hgnc":"HGNC:4738","core":true,"core_annotation":{"hgnc":"HGNC:4738","symbol_at_source":"HIST2H2AC","accession":"Q16777","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":316,"hub_weight":0.36961063547728645,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","dataset_cell:HCT116"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling","source":"project UniProt records20261017/18"},{"partner":"SETD3","hgnc":"HGNC:20493","core":true,"core_annotation":{"hgnc":"HGNC:20493","symbol_at_source":"SETD3","accession":"Q86TU7","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1463,"hub_weight":0.1817881366751496,"quality":0.65,"programmes":["pubmed:38272222"],"pmids":["38272222"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein-histidine N-methyltransferase that specifically mediates 3-methylhistidine (tele-methylhistidine) methylation of actin at 'His-73' (PubMed:30526847, PubMed:30626964, PubMed:30785395, PubMed:31388018, PubMed:31993215). Histidine methylation of actin is required for smooth muscle contraction of the laboring uterus during delivery (PubMed:30626964). Does not have protein-lysine N-methyltransferase activity and probably only catalyzes histidine methylation of actin (PubMed:30626964, PubMed:30785395, PubMed:31388018)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"SH3BGRL2":{"coreEvidence":[{"partner":"ACTB","hgnc":"HGNC:132","core":true,"core_annotation":{"hgnc":"HGNC:132","symbol_at_source":"ACTB","accession":"P60709","function":"Chromatin remodeling cofactor","target":"chromatin","pmids":["10966108"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF-like EPAFB, bBAF, SWI/SNF BRM-BRG1, NuA4, NuA4-related complex","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":706,"hub_weight":0.25717224993681986,"quality":0.65,"programmes":["pubmed:35271311"],"pmids":["35271311"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]"],"partner_location":"Cytoplasm, cytoskeleton; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Actin is a highly conserved protein that polymerizes to produce filaments that form cross-linked networks in the cytoplasm of cells (PubMed:25255767, PubMed:29581253). Actin exists in both monomeric (G-actin) and polymeric (F-actin) forms, both forms playing key functions, such as cell motility and contraction (PubMed:29581253). In addition to their role in the cytoplasmic cytoskeleton, G- and F-actin also localize in the nucleus, and regulate gene transcription and motility and repair of damaged DNA (PubMed:29925947). Plays a role in the assembly of the gamma-tubulin ring complex (gTuRC), which regulates the minus-end nucleation of alpha-beta tubulin heterodimers that grow into microtubule protafilaments (PubMed:39321809, PubMed:38609661). Part of the ACTR1A/ACTB filament around which the dynactin complex is built (By similarity). The dynactin multiprotein complex activates the molecular motor dynein for ultra-processive transport along microtubules (By similarity)","source":"project UniProt records20261017/18"},{"partner":"BMI1","hgnc":"HGNC:1066","core":true,"core_annotation":{"hgnc":"HGNC:1066","symbol_at_source":"BMI1","accession":"P35226","function":"Polycomb group (PcG) protein","target":"#","pmids":["15386022"],"complexes":"PRC1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":900,"hub_weight":0.22941573387056177,"quality":0.65,"programmes":["pubmed:34316702"],"pmids":["34316702"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens U-87 MG glioblastoma cell\", \"human-u87-mg\"]"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of a Polycomb group (PcG) multiprotein PRC1-like complex, a complex class required to maintain the transcriptionally repressive state of many genes, including Hox genes, throughout development. PcG PRC1 complex acts via chromatin remodeling and modification of histones; it mediates monoubiquitination of histone H2A 'Lys-119', rendering chromatin heritably changed in its expressibility (PubMed:15386022, PubMed:16359901, PubMed:16714294, PubMed:21772249, PubMed:25355358, PubMed:26151332, PubMed:27827373). The complex composed of RNF2, UB2D3 and BMI1 binds nucleosomes, and has activity only with nucleosomal histone H2A (PubMed:21772249, PubMed:25355358). In the PRC1-like complex, regulates the E3 ubiquitin-protein ligase activity of RNF2/RING2 (PubMed:15386022, PubMed:21772249, PubMed:26151332)","source":"project UniProt records20261017/18"},{"partner":"FOXA1","hgnc":"HGNC:5021","core":true,"core_annotation":{"hgnc":"HGNC:5021","symbol_at_source":"FOXA1","accession":"P55317","function":"Chromatin remodeling, TF","target":"chromatin, DNA","pmids":["22406422"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":397,"hub_weight":0.33445003104532556,"quality":0.65,"programmes":["pubmed:30572598"],"pmids":["30572598"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcription factor that is involved in embryonic development, establishment of tissue-specific gene expression and regulation of gene expression in differentiated tissues. Is thought to act as a 'pioneer' factor opening the compacted chromatin for other proteins through interactions with nucleosomal core histones and thereby replacing linker histones at target enhancer and/or promoter sites. Binds DNA with the consensus sequence 5'-[AC]A[AT]T[AG]TT[GT][AG][CT]T[CT]-3' (By similarity). Proposed to play a role in translating the epigenetic signatures into cell type-specific enhancer-driven transcriptional programs. Its differential recruitment to chromatin is dependent on distribution of histone H3 methylated at 'Lys-5' (H3K4me2) in estrogen-regulated genes. Involved in the development of multiple endoderm-derived organ systems such as liver, pancreas, lung and prostate; FOXA1 and FOXA2 seem to have at least in part redundant roles (By similarity). Modulates the transcriptional activity of nuclear hormone receptors. Is involved in ESR1-mediated transcription; required for ESR1 binding to the NKX2-1 promoter in breast cancer cells; binds to the RPRM promoter and is required for the estrogen-induced repression of RPRM. Involved in regulation of apoptosis by inhibiting the expression of BCL2. Involved in cell cycle regulation by activating expression of CDKN1B, alone or in conjunction with BRCA1. Originally described as a transcription activator for a number of liver genes such as AFP, albumin, tyrosine aminotransferase, PEPCK, etc. Interacts with the cis-acting regulatory regions of these genes. Involved in glucose homeostasis","source":"project UniProt records20261017/18"},{"partner":"UBE2D1","hgnc":"HGNC:12474","core":true,"core_annotation":{"hgnc":"HGNC:12474","symbol_at_source":"UBE2D1","accession":"P51668","function":"Histone modification write","target":"histone","pmids":["22438555"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":217,"hub_weight":0.4327423224079155,"quality":0.35,"programmes":["pubmed:22939629"],"pmids":["22939629"],"assays":["cofractionation"],"contexts":[],"partner_location":"Cytoplasm","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Accepts ubiquitin from the E1 complex and catalyzes its covalent attachment to other proteins (PubMed:22496338). In vitro catalyzes 'Lys-48'-linked polyubiquitination (PubMed:20061386). Mediates the selective degradation of short-lived and abnormal proteins. Functions in the E6/E6-AP-induced ubiquitination of p53/TP53. Mediates ubiquitination of PEX5 and auto-ubiquitination of STUB1, TRAF6 and TRIM63/MURF1 (PubMed:18042044, PubMed:18359941). Ubiquitinates STUB1-associated HSP90AB1 in vitro (PubMed:18042044). Lacks inherent specificity for any particular lysine residue of ubiquitin (PubMed:18042044). Essential for viral activation of IRF3 (PubMed:19854139). Mediates polyubiquitination of CYP3A4 (PubMed:19103148)","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"SH3BGRL","accession":"O75368","identity":0.644,"qcov":0.972,"tcov":0.912,"domain_context":"shared_family_context","structure_qualified":"True","function_pmids":[],"function":"","member_mechanism_evidence_available":false}]},"RIPOR3":{"coreEvidence":[{"partner":"PARP1","hgnc":"HGNC:270","core":true,"core_annotation":{"hgnc":"HGNC:270","symbol_at_source":"PARP1","accession":"P09874","function":"Chromatin remodeling","target":"histone","pmids":["20926656","17177976","17396150"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":1585,"hub_weight":0.17487435419566724,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Chromosome; Nucleus; Nucleus, nucleolus; Cytoplasm, cytosol; Chromosome; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Poly-ADP-ribosyltransferase that mediates poly-ADP-ribosylation of proteins and plays a key role in DNA repair (PubMed:17177976, PubMed:18055453, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:20388712, PubMed:21680843, PubMed:22582261, PubMed:23230272, PubMed:25043379, PubMed:26344098, PubMed:26626479, PubMed:26626480, PubMed:30104678, PubMed:31796734, PubMed:32028527, PubMed:32241924, PubMed:32358582, PubMed:33186521, PubMed:34465625, PubMed:34737271). Mediates glutamate, aspartate, serine, histidine or tyrosine ADP-ribosylation of proteins: the ADP-D-ribosyl group of NAD(+) is transferred to the acceptor carboxyl group of target residues and further ADP-ribosyl groups are transferred to the 2'-position of the terminal adenosine moiety, building up a polymer with an average chain length of 20-30 units (PubMed:19764761, PubMed:25043379, PubMed:28190768, PubMed:29954836, PubMed:35393539, PubMed:7852410, PubMed:9315851). Serine ADP-ribosylation of proteins constitutes the primary form of ADP-ribosylation of proteins in response to DNA damage (PubMed:33186521, PubMed:34874266, PubMed:41062835). Specificity for the different amino acids is conferred by interacting factors, such as HPF1 and NMNAT1 (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Following interaction with HPF1, catalyzes serine ADP-ribosylation of target proteins; HPF1 confers serine specificity by completing the PARP1 active site (PubMed:28190768, PubMed:29954836, PubMed:32028527, PubMed:33186521, PubMed:33589610, PubMed:34625544, PubMed:34874266). Also catalyzes tyrosine ADP-ribosylation of target proteins following interaction with HPF1 (PubMed:29954836, PubMed:30257210). Following interaction with NMNAT1, catalyzes glutamate and aspartate ADP-ribosylation of target proteins; NMNAT1 confers glutamate and aspartate specificity (By similarity). PARP1 initiates the repair of DNA breaks: recognizes and binds DNA breaks within chromatin and recruits HPF1, licensing serine ADP-ribosylation of target proteins, such as histones (H2BS6ADPr and H3S10ADPr), thereby promoting decompaction of chromatin and the recruitment of repair factors leading to the reparation of DNA strand breaks (PubMed:17177976, PubMed:18172500, PubMed:19344625, PubMed:19661379, PubMed:23230272, PubMed:27067600, PubMed:34465625, PubMed:34874266). HPF1 initiates serine ADP-ribosylation but restricts the polymerase activity of PARP1 in order to limit the length of poly-ADP-ribose chains (PubMed:33683197, PubMed:34732825, PubMed:34795260). In addition to base excision repair (BER) pathway, also involved in double-strand breaks (DSBs) repair: together with TIMELESS, accumulates at DNA damage sites and promotes homologous recombination repair by mediating poly-ADP-ribosylation (PubMed:26344098, PubMed:30356214). Mediates the poly-ADP-ribosylation of a number of proteins, including itself, APLF, CHFR, RPA1 and NFAT5 (PubMed:17396150, PubMed:19764761, PubMed:24906880, PubMed:34049076). In addition to proteins, also able to ADP-ribosylate DNA: catalyzes ADP-ribosylation of DNA strand break termini containing terminal phosphates and a 2'-OH group in single- and double-stranded DNA, respectively (PubMed:27471034). Required for PARP9 and DTX3L recruitment to DNA damage sites (PubMed:23230272). PARP1-dependent PARP9-DTX3L-mediated ubiquitination promotes the rapid and specific recruitment of 53BP1/TP53BP1, UIMC1/RAP80, and BRCA1 to DNA damage sites (PubMed:23230272). PARP1-mediated DNA repair in neurons plays a role in sleep: senses DNA damage in neurons and promotes sleep, facilitating efficient DNA repair (By similarity). In addition to DNA repair, also involved in other processes, such as transcription regulation, programmed cell death, membrane repair, adipogenesis and innate immunity (PubMed:15607977, PubMed:17177976, PubMed:19344625, PubMed:27256882, PubMed:32315358, PubMed:32844745, PubMed:35124853, PubMed:35393539, PubMed:35460603). Acts as a repressor of transcription: binds to nucleosomes and modulates chromatin structure in a manner similar to histone H1, thereby altering RNA polymerase II (PubMed:15607977, PubMed:22464733). Acts both as a positive and negative regulator of transcription elongation, depending on the context (PubMed:27256882, PubMed:35393539). Acts as a positive regulator of transcription elongation by mediating poly-ADP-ribosylation of NELFE, preventing RNA-binding activity of NELFE and relieving transcription pausing (PubMed:27256882). Acts as a negative regulator of transcription elongation in response to DNA damage by catalyzing poly-ADP-ribosylation of CCNT1, disrupting the phase separation activity of CCNT1 and subsequent activation of CDK9 (PubMed:35393539). Involved in replication fork progression following interaction with CARM1: mediates poly-ADP-ribosylation at replication forks, slowing fork progression (PubMed:33412112). Poly-ADP-ribose chains generated by PARP1 also play a role in poly-ADP-ribose-dependent cell death, a process named parthanatos (By similarity). Also acts as a negative regulator of the cGAS-STING pathway (PubMed:32315358, PubMed:32844745, PubMed:35460603). Acts by mediating poly-ADP-ribosylation of CGAS: PARP1 translocates into the cytosol following phosphorylation by PRKDC and catalyzes poly-ADP-ribosylation and inactivation of CGAS (PubMed:35460603). Acts as a negative regulator of adipogenesis: catalyzes poly-ADP-ribosylation of histone H2B on 'Glu-35' (H2BE35ADPr) following interaction with NMNAT1, inhibiting phosphorylation of H2B at 'Ser-36' (H2BS36ph), thereby blocking expression of pro-adipogenetic genes (By similarity). Involved in the synthesis of ATP in the nucleus, together with NMNAT1, PARG and NUDT5 (PubMed:27257257). Nuclear ATP generation is required for extensive chromatin remodeling events that are energy-consuming (PubMed:27257257). Plays a role in sister chromatid cohesion by mediating ADP-ribosylation of RSMC during S phase which promotes the interaction between RSMC and CDCA5/sororin, leading to enhanced interaction of CDCA5/sororin with the cohesin complex and promotion of sister chromatid cohesion (PubMed:41261216)\nPromotes AIFM1-mediated apoptosis (PubMed:33168626). This form, which translocates into the cytoplasm following cleavage by caspase-3 (CASP3) and caspase-7 (CASP7) in response to apoptosis, is auto-poly-ADP-ribosylated and serves as a poly-ADP-ribose carrier to induce AIFM1-mediated apoptosis (PubMed:33168626)\nThis cleavage form irreversibly binds to DNA breaks and interferes with DNA repair, promoting DNA damage-induced apoptosis","source":"project UniProt records20261017/18"},{"partner":"SCML4","hgnc":"HGNC:21397","core":true,"core_annotation":{"hgnc":"HGNC:21397","symbol_at_source":"SCML4","accession":"Q8N228","function":"Polycomb group (PcG) protein","target":"#","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":10,"hub_weight":0.9128709291752769,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Putative Polycomb group (PcG) protein. PcG proteins act by forming multiprotein complexes, which are required to maintain the transcriptionally repressive state of homeotic genes throughout development (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"HDHD3":{"coreEvidence":[{"partner":"PDP1","hgnc":"HGNC:9279","core":true,"core_annotation":{"hgnc":"HGNC:9279","symbol_at_source":"PDP1","accession":"Q9P0J1","function":"Histone modification read","target":"histone, DNA","pmids":["22150589"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":68,"hub_weight":0.6509445549041193,"quality":0.35,"programmes":["pubmed:31536960"],"pmids":["31536960"],"assays":["cofractionation"],"contexts":[],"partner_location":"Mitochondrion","partner_has_nuclear_annotation":false,"partner_location_assessed":true,"function":"Mitochondrial enzyme that catalyzes the dephosphorylation and concomitant reactivation of the alpha subunit of the E1 component of the pyruvate dehydrogenase complex (PDC), thereby stimulating the conversion of pyruvate into acetyl-CoA","source":"project UniProt records20261017/18"},{"partner":"SMYD1","hgnc":"HGNC:20986","core":true,"core_annotation":{"hgnc":"HGNC:20986","symbol_at_source":"SMYD1","accession":"Q8NB12","function":"Histone modification write","target":"histone","pmids":["22498752"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":37,"hub_weight":0.7580980435789034,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Methylates histone H3 at 'Lys-4' (H3K4me), seems able to perform both mono-, di-, and trimethylation. Acts as a transcriptional repressor. Essential for cardiomyocyte differentiation and cardiac morphogenesis","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"GPALPP1":{"coreEvidence":[{"partner":"CTBP2","hgnc":"HGNC:2495","core":true,"core_annotation":{"hgnc":"HGNC:2495","symbol_at_source":"CTBP2","accession":"P56545","function":"Histone modification write cofactor","target":"histone","pmids":["16702210"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":298,"hub_weight":0.3790490217894517,"quality":0.65,"programmes":["pubmed:26496610"],"pmids":["26496610"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HeLa epitheloid cervical carcinoma cell\", \"human-hela\"]"],"partner_location":"Nucleus; Synapse","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Corepressor targeting diverse transcription regulators. Functions in brown adipose tissue (BAT) differentiation (By similarity)\nIsoform 2 probably acts as a scaffold for specialized synapses","source":"project UniProt records20261017/18"},{"partner":"H2BC8","hgnc":"HGNC:4746","core":true,"core_annotation":{"hgnc":"HGNC:4746","symbol_at_source":"HIST1H2BG","accession":"P62807","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":546,"hub_weight":0.28964222318174615,"quality":0.4,"programmes":["pubmed:25281560","pubmed:34079125"],"pmids":["25281560","34079125"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of nucleosome. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling\nHas broad antibacterial activity. May contribute to the formation of the functional antimicrobial barrier of the colonic epithelium, and to the bactericidal activity of amniotic fluid","source":"project UniProt records20261017/18"},{"partner":"SUPT6H","hgnc":"HGNC:11470","core":true,"core_annotation":{"hgnc":"HGNC:11470","symbol_at_source":"SUPT6H","accession":"Q7KZ85","function":"Histone modification erase cofactor","target":"histone","pmids":["23503590"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":188,"hub_weight":0.45834924851410563,"quality":0.35,"programmes":["pubmed:35831314"],"pmids":["35831314"],"assays":["cofractionation"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone H3-H4 chaperone that plays a key role in the regulation of transcription elongation and mRNA processing. Enhances the transcription elongation by RNA polymerase II (RNAPII) and is also required for the efficient activation of transcriptional elongation by the HIV-1 nuclear transcriptional activator, Tat. Besides chaperoning histones in transcription, acts to transport and splice mRNA by forming a complex with IWS1 and the C-terminal domain (CTD) of the RNAPII subunit RPB1 (POLR2A). The SUPT6H:IWS1:CTD complex recruits mRNA export factors (ALYREF/THOC4, EXOSC10) as well as histone modifying enzymes (such as SETD2), to ensure proper mRNA splicing, efficient mRNA export and elongation-coupled H3K36 methylation, a signature chromatin mark of active transcription. SUPT6H via its association with SETD1A, regulates both class-switch recombination and somatic hypermutation through formation of H3K4me3 epigenetic marks on activation-induced cytidine deaminase (AICDA) target loci. Promotes the activation of the myogenic gene program by entailing erasure of the repressive H3K27me3 epigenetic mark through stabilization of the chromatin interaction of the H3K27 demethylase KDM6A","source":"project UniProt records20261017/18"},{"partner":"UBE2H","hgnc":"HGNC:12484","core":true,"core_annotation":{"hgnc":"HGNC:12484","symbol_at_source":"UBE2H","accession":"P62256","function":"Histone modification write","target":"histone","pmids":["8132613"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":1345,"hub_weight":0.18932061141568826,"quality":0.65,"programmes":["pubmed:38113892"],"pmids":["38113892"],"assays":["capture_association"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Accepts ubiquitin from the E1 complex and catalyzes its covalent attachment to other proteins (PubMed:17588522, PubMed:20061386, PubMed:8132613). E2 ubiquitin conjugating enzyme that transfers ubiquitin to MAEA, a core component of the CTLH E3 ubiquitin-protein ligase complex (PubMed:29911972). In vitro catalyzes 'Lys-11'- and 'Lys-48'-linked polyubiquitination (PubMed:20061386). Capable, in vitro, to ubiquitinate histone H2A (PubMed:8132613)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"GPATCH2L":{"coreEvidence":[{"partner":"CSNK2A1","hgnc":"HGNC:2457","core":true,"core_annotation":{"hgnc":"HGNC:2457","symbol_at_source":"CSNK2A1","accession":"P68400","function":"Histone modification","target":"histone","pmids":["24217316","22325352"],"complexes":"RING2-FBRS","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":769,"hub_weight":0.2470831055537004,"quality":0.75,"programmes":["BioPlex","CCSB_binary_maps","pubmed:32707033","pubmed:35271311","pubmed:36736316"],"pmids":["28514442","32296183","32707033","33961781","35271311","36736316"],"assays":["binary_reporter","capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","IntAct_host:[\"Homo sapiens HEK293flp-in T-REX embryonic kidney cell\", \"human-293lp-In T-REx\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of a constitutively active serine/threonine-protein kinase complex that phosphorylates a large number of substrates containing acidic residues C-terminal to the phosphorylated serine or threonine (PubMed:11239457, PubMed:11704824, PubMed:16193064, PubMed:18411307, PubMed:18583988, PubMed:18678890, PubMed:19188443, PubMed:20545769, PubMed:20625391, PubMed:22017874, PubMed:22406621, PubMed:24962073, PubMed:30898438, PubMed:31439799). Regulates numerous cellular processes, such as cell cycle progression, apoptosis and transcription, as well as viral infection (PubMed:12631575, PubMed:19387551, PubMed:19387552). May act as a regulatory node which integrates and coordinates numerous signals leading to an appropriate cellular response (PubMed:12631575, PubMed:19387551, PubMed:19387552). During mitosis, functions as a component of the p53/TP53-dependent spindle assembly checkpoint (SAC) that maintains cyclin-B-CDK1 activity and G2 arrest in response to spindle damage (PubMed:11704824, PubMed:19188443). Also required for p53/TP53-mediated apoptosis, phosphorylating 'Ser-392' of p53/TP53 following UV irradiation (PubMed:11239457). Phosphorylates a number of DNA repair proteins in response to DNA damage, such as MDC1, MRE11, RAD9A, RAD51 and HTATSF1, promoting their recruitment to DNA damage sites (PubMed:18411307, PubMed:18583988, PubMed:18678890, PubMed:20545769, PubMed:21482717, PubMed:22325354, PubMed:26811421, PubMed:28512243, PubMed:30898438, PubMed:35597237). Can also negatively regulate apoptosis (PubMed:16193064, PubMed:22184066). Phosphorylates the caspases CASP9 and CASP2 and the apoptotic regulator NOL3 (PubMed:16193064). Phosphorylation protects CASP9 from cleavage and activation by CASP8, and inhibits the dimerization of CASP2 and activation of CASP8 (PubMed:16193064). Phosphorylates YY1, protecting YY1 from cleavage by CASP7 during apoptosis (PubMed:22184066). Regulates transcription by direct phosphorylation of RNA polymerases I, II, III and IV (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552, PubMed:23123191). Also phosphorylates and regulates numerous transcription factors including NF-kappa-B, STAT1, CREB1, IRF1, IRF2, ATF1, ATF4, SRF, MAX, JUN, FOS, MYC and MYB (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552, PubMed:23123191). Phosphorylates Hsp90 and its co-chaperones FKBP4 and CDC37, which is essential for chaperone function (PubMed:19387550). Mediates sequential phosphorylation of FNIP1, promoting its gradual interaction with Hsp90, leading to activate both kinase and non-kinase client proteins of Hsp90 (PubMed:30699359). Regulates Wnt signaling by phosphorylating CTNNB1 and the transcription factor LEF1 (PubMed:19387549). Acts as an ectokinase that phosphorylates several extracellular proteins (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552). During viral infection, phosphorylates various proteins involved in the viral life cycles of EBV, HSV, HBV, HCV, HIV, CMV and HPV (PubMed:12631575, PubMed:19387550, PubMed:19387551, PubMed:19387552). Phosphorylates PML at 'Ser-565' and primes it for ubiquitin-mediated degradation (PubMed:20625391, PubMed:22406621). Plays an important role in the circadian clock function by phosphorylating BMAL1 at 'Ser-90' which is pivotal for its interaction with CLOCK and which controls CLOCK nuclear entry (By similarity). Phosphorylates CCAR2 at 'Thr-454' in gastric carcinoma tissue (PubMed:24962073). Phosphorylates FMR1, promoting FMR1-dependent formation of a membraneless compartment (PubMed:30765518, PubMed:31439799). May phosphorylate histone H2A on 'Ser-1' (PubMed:38334665)","source":"project UniProt records20261017/18"},{"partner":"PRMT1","hgnc":"HGNC:5187","core":true,"core_annotation":{"hgnc":"HGNC:5187","symbol_at_source":"PRMT1","accession":"Q99873","function":"Histone modification write","target":"histone","pmids":["11387442"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":695,"hub_weight":0.2590638800754199,"quality":0.75,"programmes":["pubmed:23455924"],"pmids":["23455924"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Nucleus, nucleoplasm; Cytoplasm; Cytoplasm, cytosol; Lysosome membrane","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Arginine methyltransferase that methylates (mono and asymmetric dimethylation) the guanidino nitrogens of arginyl residues present in proteins such as ESR1, histone H2, H3 and H4, FMR1, ILF3, HNRNPA1, HNRNPD, NFATC2IP, SUPT5H, TAF15, EWS, HABP4, SERBP1, RBM15, FOXO1, CHTOP, MAP3K5/ASK1, MICU1 and NPRL2 (PubMed:10749851, PubMed:15741314, PubMed:16879614, PubMed:18951090, PubMed:22095282, PubMed:25284789, PubMed:26575292, PubMed:26876602, PubMed:27642082, PubMed:30765518, PubMed:31257072, PubMed:38006878). Constitutes the main enzyme that mediates monomethylation and asymmetric dimethylation of histone H4 'Arg-3' (H4R3me1 and H4R3me2a, respectively), a specific tag for epigenetic transcriptional activation. May be involved in the regulation of TAF15 transcriptional activity, act as an activator of estrogen receptor (ER)-mediated transactivation, play a key role in neurite outgrowth and act as a negative regulator of megakaryocytic differentiation, by modulating p38 MAPK pathway. Methylates RBM15, promoting ubiquitination and degradation of RBM15 (PubMed:26575292). Methylates MRE11 and TP53BP1, promoting the DNA damage response (PubMed:15741314, PubMed:16294045, PubMed:29651020). Methylates FOXO1 and retains it in the nucleus increasing its transcriptional activity (PubMed:18951090). Methylates CHTOP and this methylation is critical for its 5-hydroxymethylcytosine (5hmC)-binding activity (PubMed:25284789). Methylates MAP3K5/ASK1 at 'Arg-78' and 'Arg-80' which promotes association of MAP3K5 with thioredoxin and negatively regulates MAP3K5 association with TRAF2, inhibiting MAP3K5 stimulation and MAP3K5-induced activation of JNK (PubMed:22095282). Methylates H4R3 in genes involved in glioblastomagenesis in a CHTOP- and/or TET1-dependent manner (PubMed:25284789). Plays a role in regulating alternative splicing in the heart (By similarity). Methylates NPRL2 at 'Arg-78' leading to inhibition of its GTPase activator activity and then the GATOR1 complex and consequently inducing timely mTORC1 activation under methionine-sufficient conditions (PubMed:38006878). Methylates the C-terminus of DSP, promoting its phosphorylation by GSK3B and subsequent recruitment to desmosome cell-cell junctions (PubMed:25733715)","source":"project UniProt records20261017/18"},{"partner":"SUV39H1","hgnc":"HGNC:11479","core":true,"core_annotation":{"hgnc":"HGNC:11479","symbol_at_source":"SUV39H1","accession":"O43463","function":"Histone modification write, Histone modification write","target":"histone","pmids":["10949293"],"complexes":"eNoSc","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":191,"hub_weight":0.45548751867427695,"quality":0.75,"programmes":["pubmed:23455924"],"pmids":["23455924"],"assays":["binary_reporter","capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293 embryonic kidney cell\", \"human-293\"]"],"partner_location":"Nucleus; Chromosome; Nucleus lamina; Nucleus, nucleoplasm; Chromosome, centromere; Cytoplasmic vesicle, phagosome lumen; Cell membrane","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone methyltransferase that specifically mediates trimethylation of 'Lys-9' of histone H3 (H3K9me3) using monomethylated H3 'Lys-9' (H3K9me1) as substrate (PubMed:10949293, PubMed:11242053, PubMed:18004385, PubMed:40440427). Also weakly methylates histone H1 (in vitro) (PubMed:10949293). H3 'Lys-9' trimethylation represents a specific tag for epigenetic transcriptional repression by recruiting HP1 (CBX1, CBX3 and/or CBX5) proteins to methylated histones (PubMed:10949293, PubMed:11242053, PubMed:18004385). Mainly functions in heterochromatin regions, thereby playing a central role in the establishment of constitutive heterochromatin at pericentric and telomere regions (By similarity). H3 'Lys-9' trimethylation is also required to direct DNA methylation at pericentric repeats (PubMed:41094145). SUV39H1 is targeted to histone H3 via its interaction with RB1 and is involved in many processes, such as repression of MYOD1-stimulated differentiation, regulation of the control switch for exiting the cell cycle and entering differentiation, repression by the PML-RARA fusion protein, BMP-induced repression, repression of switch recombination to IgA and regulation of telomere length (PubMed:11484059, PubMed:14765126, PubMed:16449642, PubMed:16818776, PubMed:16858404, PubMed:30111536). Involved in the maintenance of H3K9me3 mark following DNA replication, when histone marks are diluted: HP1 recognizes the preexisting H3K9me3 mark and serves as a platform to recruit SUV39H1 to modify the adjacent newly incorporated histones (PubMed:10949293, PubMed:11242053, PubMed:40440427). Component of the eNoSC (energy-dependent nucleolar silencing) complex, a complex that mediates silencing of rDNA in response to intracellular energy status and acts by recruiting histone-modifying enzymes (PubMed:18485871). The eNoSC complex is able to sense the energy status of cell: upon glucose starvation, elevation of NAD(+)/NADP(+) ratio activates SIRT1, leading to histone H3 deacetylation followed by dimethylation of H3 at 'Lys-9' (H3K9me2) by SUV39H1 and the formation of silent chromatin in the rDNA locus (PubMed:18485871). Recruited by the large PER complex to the E-box elements of the circadian target genes such as PER2 itself or PER1, contributes to the conversion of local chromatin to a heterochromatin-like repressive state through H3 'Lys-9' trimethylation (By similarity)\n(Microbial infection) Plays a role in defense against mycobacterial infections. Methylates M.tuberculosis HupB on 'Lys-140', probably methylates HupB of M.bovis also. Methylation has an inhibitory effect on mycobacterial growth in the host. Macrophages expressing about 60% SUV39H1 are slightly more susceptible to M.bovis or M.tuberculosis infection. Chaetocin (an inhibitor of this enzyme) increases macrophage survival of M.tuberculosis. This protein inhibits biofilm formation by M.tuberculosis via 'Lys-140' trimethylation","source":"project UniProt records20261017/18"},{"partner":"PRDM14","hgnc":"HGNC:14001","core":true,"core_annotation":{"hgnc":"HGNC:14001","symbol_at_source":"PRDM14","accession":"Q9GZV8","function":"DNA modification","target":"DNA","pmids":["24335252"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":73,"hub_weight":0.6375767130633383,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["25416956","32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Transcription factor that has both positive and negative roles on transcription. Required for the maintenance of embryonic stem cell identity and the reacquisition of pluripotency in somatic cells. May play an essential role in germ cell development at 2 levels: the reacquisition of potential pluripotency, including SOX2 up-regulation, and successful epigenetic reprogramming, characterized by EHMT1 repression. Its association with CBFA2T2 is required for the functions in pluripotency and germ cell formation (By similarity). Directly up-regulates the expression of pluripotency gene POU5F1 through its proximal enhancer. Binds to the DNA consensus sequence 5'-GGTC[TC]CTAA-3'","source":"project UniProt records20261017/18"},{"partner":"KDM1A","hgnc":"HGNC:29079","core":true,"core_annotation":{"hgnc":"HGNC:29079","symbol_at_source":"KDM1A","accession":"O60341","function":"Histone modification erase","target":"histone","pmids":["16223729"],"complexes":"NuRD, BHC, SCL","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":641,"hub_weight":0.26899609689495085,"quality":0.75,"programmes":["pubmed:23455924"],"pmids":["23455924"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Histone demethylase that can demethylate both 'Lys-4' (H3K4me) and 'Lys-9' (H3K9me) of histone H3, thereby acting as a coactivator or a corepressor, depending on the context (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:16079795, PubMed:16140033, PubMed:16223729, PubMed:27292636). Acts by oxidizing the substrate by FAD to generate the corresponding imine that is subsequently hydrolyzed (PubMed:15620353, PubMed:15811342, PubMed:16079794, PubMed:21300290, PubMed:26214369). Acts as a corepressor by mediating demethylation of H3K4me, a specific tag for epigenetic transcriptional activation. Demethylates both mono- (H3K4me1) and di-methylated (H3K4me2) (PubMed:15620353, PubMed:20389281, PubMed:21300290, PubMed:23721412). May play a role in the repression of neuronal genes. Alone, it is unable to demethylate H3K4me on nucleosomes and requires the presence of RCOR1/CoREST to achieve such activity (PubMed:16079794, PubMed:16140033, PubMed:16885027, PubMed:21300290, PubMed:23721412). Also acts as a coactivator of androgen receptor (AR)-dependent transcription, by being recruited to AR target genes and mediating demethylation of H3K9me, a specific tag for epigenetic transcriptional repression. The presence of PRKCB in AR-containing complexes, which mediates phosphorylation of 'Thr-6' of histone H3 (H3T6ph), a specific tag that prevents demethylation H3K4me, prevents H3K4me demethylase activity of KDM1A (PubMed:16079795). Demethylates di-methylated 'Lys-370' of p53/TP53 which prevents interaction of p53/TP53 with TP53BP1 and represses p53/TP53-mediated transcriptional activation. Demethylates and stabilizes the DNA methylase DNMT1 (PubMed:29691401). Demethylates methylated 'Lys-42' and methylated 'Lys-117' of SOX2 (PubMed:29358331). Required for gastrulation during embryogenesis. Component of a RCOR/GFI/KDM1A/HDAC complex that suppresses, via histone deacetylase (HDAC) recruitment, a number of genes implicated in multilineage blood cell development (PubMed:16079794, PubMed:16140033). Facilitates epithelial-to-mesenchymal transition by acting as an effector of SNAI1-mediated transcription repression of epithelial markers E-cadherin/CDH1, CDN7 and KRT8 (PubMed:20562920, PubMed:27292636). Required for the maintenance of the silenced state of the SNAI1 target genes E-cadherin/CDH1 and CDN7 (PubMed:20389281). Required for the repression of GIPR expression (PubMed:34655521, PubMed:34906447)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)\nNeuron-specific histone demethylase that demethylates mono- and dimethylated 'Lys-20' of histone H4 (H4K20me1 and H4K20me2), a chromatin repressive mark (PubMed:26214369). This demethylation is crucial for the initiation and elongation of neuronal activity-regulated genes, required for spatial learning and memory (By similarity). Mediates H3K9me2 demethylation through cooperation with the supervillin protein (SVIL), and this H3K9 demethylase activity is essential for regulating gene expression during neuronal differentiation (PubMed:25684206)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"KRABD3":{"coreEvidence":[{"partner":"CUL3","hgnc":"HGNC:2553","core":true,"core_annotation":{"hgnc":"HGNC:2553","symbol_at_source":"CUL3","accession":"Q13618","function":"Histone modification write","target":"histone","pmids":["15897469"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":2139,"hub_weight":0.15113398071880554,"quality":0.65,"programmes":["pubmed:35563538"],"pmids":["35563538"],"assays":["capture_association"],"contexts":[],"partner_location":"Nucleus; Golgi apparatus; Cell projection, cilium, flagellum; Cytoplasm, cytoskeleton, spindle; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Core component of multiple cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complexes which mediate the ubiquitination and subsequent proteasomal degradation of target proteins (PubMed:29695787). BCR complexes and ARIH1 collaborate in tandem to mediate ubiquitination of target proteins (PubMed:27565346). As a scaffold protein may contribute to catalysis through positioning of the substrate and the ubiquitin-conjugating enzyme. The E3 ubiquitin-protein ligase activity of the complex is dependent on the neddylation of the cullin subunit and is inhibited by the association of the deneddylated cullin subunit with TIP120A/CAND1. The functional specificity of the BCR complex depends on the BTB domain-containing protein as the substrate recognition component. BCR(KLHL42) is involved in ubiquitination of KATNA1. BCR(SPOP) is involved in ubiquitination of BMI1/PCGF4, BRMS1, MACROH2A1 and DAXX, GLI2 and GLI3. Can also form a cullin-RING-based BCR (BTB-CUL3-RBX1) E3 ubiquitin-protein ligase complex containing homodimeric SPOPL or the heterodimer formed by SPOP and SPOPL; these complexes have lower ubiquitin ligase activity. BCR(KLHL9-KLHL13) controls the dynamic behavior of AURKB on mitotic chromosomes and thereby coordinates faithful mitotic progression and completion of cytokinesis. BCR(KLHL12) is involved in ER-Golgi transport by regulating the size of COPII coats, thereby playing a key role in collagen export, which is required for embryonic stem (ES) cells division: BCR(KLHL12) acts by mediating monoubiquitination of SEC31 (SEC31A or SEC31B) (PubMed:22358839, PubMed:27716508). BCR(KLHL3) acts as a regulator of ion transport in the distal nephron; by mediating ubiquitination of WNK4 (PubMed:23387299, PubMed:23453970, PubMed:23576762). The BCR(KLHL20) E3 ubiquitin ligase complex is involved in interferon response and anterograde Golgi to endosome transport: it mediates both ubiquitination leading to degradation and 'Lys-33'-linked ubiquitination (PubMed:20389280, PubMed:21670212, PubMed:21840486, PubMed:24768539). The BCR(KLHL21) E3 ubiquitin ligase complex regulates localization of the chromosomal passenger complex (CPC) from chromosomes to the spindle midzone in anaphase and mediates the ubiquitination of AURKB (PubMed:19995937). The BCR(KLHL22) ubiquitin ligase complex mediates monoubiquitination of PLK1, leading to PLK1 dissociation from phosphoreceptor proteins and subsequent removal from kinetochores, allowing silencing of the spindle assembly checkpoint (SAC) and chromosome segregation (PubMed:23455478). The BCR(KLHL22) ubiquitin ligase complex is also responsible for the amino acid-stimulated 'Lys-48' polyubiquitination and proteasomal degradation of DEPDC5. Through the degradation of DEPDC5, releases the GATOR1 complex-mediated inhibition of the TORC1 pathway (PubMed:29769719). The BCR(KLHL25) ubiquitin ligase complex is involved in translational homeostasis by mediating ubiquitination and subsequent degradation of hypophosphorylated EIF4EBP1 (4E-BP1) (PubMed:22578813). The BCR(KLHL25) ubiquitin ligase complex is also involved in lipid synthesis by mediating ubiquitination and degradation of ACLY (PubMed:27664236). The BCR(KBTBD8) complex acts by mediating monoubiquitination of NOLC1 and TCOF1, leading to remodel the translational program of differentiating cells in favor of neural crest specification (PubMed:26399832). Involved in ubiquitination of cyclin E and of cyclin D1 (in vitro) thus involved in regulation of G1/S transition. Involved in the ubiquitination of KEAP1, ENC1 and KLHL41 (PubMed:15983046). In concert with ATF2 and RBX1, promotes degradation of KAT5 thereby attenuating its ability to acetylate and activate ATM. The BCR(KCTD17) E3 ubiquitin ligase complex mediates ubiquitination and degradation of TCHP, a down-regulator of cilium assembly, thereby inducing ciliogenesis (PubMed:25270598). The BCR(KLHL24) E3 ubiquitin ligase complex mediates ubiquitination of KRT14, controls KRT14 levels during keratinocytes differentiation, and is essential for skin integrity (PubMed:27798626). The BCR(KLHL18) E3 ubiquitin ligase complex mediates the ubiquitination of AURKA leading to its activation at the centrosome which is required for initiating mitotic entry (PubMed:23213400). The BCR(KEAP1) E3 ubiquitin ligase complex acts as a key sensor of oxidative and electrophilic stress by mediating ubiquitination and degradation of NFE2L2/NRF2, a transcription factor regulating expression of many cytoprotective genes (PubMed:15601839, PubMed:16006525). As part of the CUL3(KBTBD6/7) E3 ubiquitin ligase complex functions mediates 'Lys-48' ubiquitination and proteasomal degradation of TIAM1 (PubMed:25684205). By controlling the ubiquitination of that RAC1 guanine exchange factors (GEF), regulates RAC1 signal transduction and downstream biological processes including the organization of the cytoskeleton, cell migration and cell proliferation (PubMed:25684205). The BCR(KBTBD4) E3 ubiquitin ligase complex targets CoREST corepressor complex components RCOR1, KDM1A/LSD1 and HDAC2 for proteasomal degradation with RCOR1 likely to be the primary target while degradation of KDM1A and HDAC2 is likely due to their association with RCOR1 (PubMed:33417871). It also targets RCOR3, MIER2 and MIER3 for proteasomal degradation as well as associated proteins ZNF217 and RREB1 with degradation being dependent on the presence of an ELM2 domain in the target proteins (PubMed:36997086). The BCR(ARMC5) complex mediates premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation by mediating ubiquitination of Pol II subunit POLR2A (PubMed:35687106, PubMed:38225631, PubMed:39504960, PubMed:39667934). Required for 'Lys-63'-linked ubiquitination of large ribosomal subunit protein MRPL12 (PubMed:37526061). Protects against human enterovirus D68 infection by mediating the ubiquitination and subsequent degradation of viral protein VP1 (PubMed:40396757)","source":"project UniProt records20261017/18"},{"partner":"PRMT2","hgnc":"HGNC:5186","core":true,"core_annotation":{"hgnc":"HGNC:5186","symbol_at_source":"PRMT2","accession":"P55345","function":"Histone modification write","target":"histone","pmids":["19405910"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":82,"hub_weight":0.6154574548966637,"quality":0.65,"programmes":["BioPlex"],"pmids":["26186194","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus; Nucleus; Cytoplasm; Nucleus; Nucleus, nucleolus; Nucleus; Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Arginine methyltransferase that methylates the guanidino nitrogens of arginyl residues in proteins such as STAT3, FBL, histone H4 (PubMed:19405910). Acts as a coactivator (with NCOA2) of the androgen receptor (AR)-mediated transactivation (PubMed:17587566). Acts as a coactivator (with estrogen) of estrogen receptor (ER)-mediated transactivation (PubMed:12039952). Enhances PGR, PPARG, RARA-mediated transactivation (PubMed:12039952). May inhibit NF-kappa-B transcription and promote apoptosis (PubMed:16648481). Represses E2F1 transcriptional activity (in a RB1-dependent manner) (By similarity). May be involved in growth regulation (By similarity). Involved in PRMT2IP-mediated inhibition of the microglial inflammatory responses through suppression of NF-kappa-B signaling, thereby reducing the production of pro-inflammatory cytokines (PubMed:38892217)","source":"project UniProt records20261017/18"},{"partner":"TRIM27","hgnc":"HGNC:9975","core":true,"core_annotation":{"hgnc":"HGNC:9975","symbol_at_source":"TRIM27","accession":"P14373","function":"Histone modification erase cofactor","target":"#","pmids":["19351825"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":414,"hub_weight":0.32826608214930636,"quality":0.65,"programmes":["BioPlex","pubmed:40205054"],"pmids":["28514442","33961781","40205054"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","IntAct_host:[\"Homo sapiens U2OS osteosarcoma cell\", \"human-u2os\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body; Early endosome; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that mediates ubiquitination of various substrates and thereby plays a role in diffent processes including proliferation, innate immunity, apoptosis, immune response or autophagy (PubMed:22829933, PubMed:24144979, PubMed:29688809, PubMed:36111389). Ubiquitinates PIK3C2B and inhibits its activity by mediating the formation of 'Lys-48'-linked polyubiquitin chains; the function inhibits CD4 T-cell activation. Acts as a regulator of retrograde transport: together with MAGEL2, mediates the formation of 'Lys-63'-linked polyubiquitin chains at 'Lys-220' of WASHC1, leading to promote endosomal F-actin assembly (PubMed:23452853). Has a transcriptional repressor activity by cooperating with EPC1. Induces apoptosis by activating Jun N-terminal kinase and p38 kinase and also increases caspase-3-like activity independently of mitochondrial events. May function in male germ cell development. Has DNA-binding activity and preferentially bound to double-stranded DNA. Forms a complex with and ubiquitinates the ubiquitin-specific protease USP7, which in turn deubiquitinates RIPK1 resulting in the positive regulation of TNF-induced apoptosis (PubMed:24144979). In addition, acts with USP7 or PTPN11 as an inhibitor of the antiviral signaling pathway by promoting kinase TBK1 ubiquitination and degradation (PubMed:26358190, PubMed:29688809). Acts as a negative regulator of NOD2 signaling by mediating ubiquitination of NOD2, promoting its degradation by the proteasome (PubMed:22829933). Alternatively, facilitates mitophagy via stabilization of active TBK1 (PubMed:36111389). Negatively regulates autophagy flux under basal conditions by directly polyubiquitinating ULK1 (PubMed:35670107). During starvation-induced autophagy, catalyzes non-degradative ubiquitination of the kinase STK38L promoting its activation and phosphorylation of ULK1 leading to its ubiquitination and degradation to restrain the amplitude and duration of autophagy (PubMed:35670107)\n(Microbial infection) Positively regulates hepatitis C virus replication by suppressing type I IFN response during infection","source":"project UniProt records20261017/18"},{"partner":"TFPT","hgnc":"HGNC:13630","core":true,"core_annotation":{"hgnc":"HGNC:13630","symbol_at_source":"TFPT","accession":"P0C1Z6","function":"Chromatin remodeling cofactor, DNA modification","target":"chromatin","pmids":["16230350"],"complexes":"Ino80","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":132,"hub_weight":0.5241424183609592,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Appears to promote apoptosis in a p53/TP53-independent manner\nPutative regulatory component of the chromatin remodeling INO80 complex which is involved in transcriptional regulation, DNA replication and probably DNA repair","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"LDLRAD1":{"coreEvidence":[{"partner":"ATR","hgnc":"HGNC:882","core":true,"core_annotation":{"hgnc":"HGNC:882","symbol_at_source":"ATR","accession":"Q13535","function":"Histone modification write","target":"histone","pmids":["11673449"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":530,"hub_weight":0.29361010975735174,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome; Nucleus envelope","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine protein kinase which activates checkpoint signaling upon genotoxic stresses such as ionizing radiation (IR), ultraviolet light (UV), or DNA replication stalling, thereby acting as a DNA damage sensor (PubMed:10597277, PubMed:10608806, PubMed:10859164, PubMed:11721054, PubMed:12791985, PubMed:12814551, PubMed:14657349, PubMed:14729973, PubMed:14742437, PubMed:15210935, PubMed:15496423, PubMed:16260606, PubMed:21144835, PubMed:21777809, PubMed:23273981, PubMed:25083873, PubMed:27723717, PubMed:27723720, PubMed:30139873, PubMed:33848395, PubMed:37788673, PubMed:37832547, PubMed:9427750, PubMed:9636169). Recognizes the substrate consensus sequence [ST]-Q (PubMed:10597277, PubMed:10608806, PubMed:10859164, PubMed:11721054, PubMed:12791985, PubMed:12814551, PubMed:14657349, PubMed:14729973, PubMed:14742437, PubMed:15210935, PubMed:15496423, PubMed:16260606, PubMed:21144835, PubMed:23273981, PubMed:27723717, PubMed:27723720, PubMed:33848395, PubMed:9427750, PubMed:9636169). Phosphorylates BRCA1, CHEK1, MCM2, RAD17, RBBP8, RPA2, SMC1 and p53/TP53, which collectively inhibit DNA replication and mitosis and promote DNA repair, recombination and apoptosis (PubMed:11114888, PubMed:11418864, PubMed:11865061, PubMed:21777809, PubMed:23273981, PubMed:25083873, PubMed:9925639). Phosphorylates 'Ser-139' of histone variant H2AX at sites of DNA damage, thereby regulating DNA damage response mechanism (PubMed:11673449). Required for FANCD2 ubiquitination (PubMed:15314022). Critical for maintenance of fragile site stability and efficient regulation of centrosome duplication (PubMed:12526805). Acts as a regulator of the S-G2 transition by restricting the activity of CDK1 during S-phase to prevent premature entry into G2 (PubMed:30139873). Acts as a regulator of the nuclear envelope integrity in response to DNA damage and stress (PubMed:25083873, PubMed:37788673, PubMed:37832547). Acts as a mechanical stress sensor at the nuclear envelope: relocalizes to the nuclear envelope in response to mechanical stress and mediates a checkpoint via phosphorylation of CHEK1 (PubMed:25083873). Also promotes nuclear envelope rupture in response to DNA damage by mediating phosphorylation of LMNA at 'Ser-282', leading to lamin disassembly (PubMed:37832547). Involved in the inflammatory response to genome instability and double-stranded DNA breaks: acts by localizing to micronuclei arising from genome instability and catalyzing phosphorylation of LMNA at 'Ser-395', priming LMNA for subsequent phosphorylation by CDK1 and micronuclei envelope rupture (PubMed:37788673). The rupture of micronuclear envelope triggers the cGAS-STING pathway thereby activating the type I interferon response and innate immunity (PubMed:37788673). Positively regulates the restart of stalled replication forks following activation by the KHDC3L-OOEP scaffold complex (By similarity)","source":"project UniProt records20261017/18"},{"partner":"CDC6","hgnc":"HGNC:1744","core":true,"core_annotation":{"hgnc":"HGNC:1744","symbol_at_source":"CDC6","accession":"Q99741","function":"Chromatin remodeling","target":"chromatin","pmids":["22358331"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":86,"hub_weight":0.6063390625908325,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in the initiation of DNA replication. Also participates in checkpoint controls that ensure DNA replication is completed before mitosis is initiated","source":"project UniProt records20261017/18"},{"partner":"CHEK1","hgnc":"HGNC:1925","core":true,"core_annotation":{"hgnc":"HGNC:1925","symbol_at_source":"CHEK1","accession":"O14757","function":"Histone modification write","target":"histone","pmids":[],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":155,"hub_weight":0.4938647983247948,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome; Cytoplasm; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Serine/threonine-protein kinase which is required for checkpoint-mediated cell cycle arrest and activation of DNA repair in response to the presence of DNA damage or unreplicated DNA (PubMed:11535615, PubMed:12399544, PubMed:12446774, PubMed:14559997, PubMed:14988723, PubMed:15311285, PubMed:15650047, PubMed:15665856, PubMed:32357935). May also negatively regulate cell cycle progression during unperturbed cell cycles (PubMed:11535615, PubMed:12399544, PubMed:12446774, PubMed:14559997, PubMed:14988723, PubMed:15311285, PubMed:15650047, PubMed:15665856). This regulation is achieved by a number of mechanisms that together help to preserve the integrity of the genome (PubMed:11535615, PubMed:12399544, PubMed:12446774, PubMed:14559997, PubMed:14988723, PubMed:15311285, PubMed:15650047, PubMed:15665856). Recognizes the substrate consensus sequence [R-X-X-S/T] (PubMed:11535615, PubMed:12399544, PubMed:12446774, PubMed:14559997, PubMed:14988723, PubMed:15311285, PubMed:15650047, PubMed:15665856). Binds to and phosphorylates CDC25A, CDC25B and CDC25C (PubMed:12676583, PubMed:12676925, PubMed:12759351, PubMed:14559997, PubMed:14681206, PubMed:19734889, PubMed:9278511). Phosphorylation of CDC25A at 'Ser-178' and 'Thr-507' and phosphorylation of CDC25C at 'Ser-216' creates binding sites for 14-3-3 proteins which inhibit CDC25A and CDC25C (PubMed:9278511). Phosphorylation of CDC25A at 'Ser-76', 'Ser-124', 'Ser-178', 'Ser-279' and 'Ser-293' promotes proteolysis of CDC25A (PubMed:12676583, PubMed:12676925, PubMed:12759351, PubMed:14681206, PubMed:19734889, PubMed:9278511). Phosphorylation of CDC25A at 'Ser-76' primes the protein for subsequent phosphorylation at 'Ser-79', 'Ser-82' and 'Ser-88' by NEK11, which is required for polyubiquitination and degradation of CDCD25A (PubMed:19734889, PubMed:20090422, PubMed:9278511). Inhibition of CDC25 leads to increased inhibitory tyrosine phosphorylation of CDK-cyclin complexes and blocks cell cycle progression (PubMed:9278511). Also phosphorylates NEK6 (PubMed:18728393). Binds to and phosphorylates RAD51 at 'Thr-309', which promotes the release of RAD51 from BRCA2 and enhances the association of RAD51 with chromatin, thereby promoting DNA repair by homologous recombination (PubMed:15665856). Phosphorylates multiple sites within the C-terminus of TP53, which promotes activation of TP53 by acetylation and promotes cell cycle arrest and suppression of cellular proliferation (PubMed:10673501, PubMed:15659650, PubMed:16511572). Also promotes repair of DNA cross-links through phosphorylation of FANCE (PubMed:17296736). Binds to and phosphorylates TLK1 at 'Ser-743', which prevents the TLK1-dependent phosphorylation of the chromatin assembly factor ASF1A (PubMed:12660173, PubMed:12955071). This may enhance chromatin assembly both in the presence or absence of DNA damage (PubMed:12660173, PubMed:12955071). May also play a role in replication fork maintenance through regulation of PCNA (PubMed:18451105). May regulate the transcription of genes that regulate cell-cycle progression through the phosphorylation of histones (By similarity). Phosphorylates histone H3.1 (to form H3T11ph), which leads to epigenetic inhibition of a subset of genes (By similarity). May also phosphorylate RB1 to promote its interaction with the E2F family of transcription factors and subsequent cell cycle arrest (PubMed:17380128). Phosphorylates SPRTN, promoting SPRTN recruitment to chromatin (PubMed:31316063). Reduces replication stress and activates the G2/M checkpoint, by phosphorylating and inactivating PABIR1/FAM122A and promoting the serine/threonine-protein phosphatase 2A-mediated dephosphorylation and stabilization of WEE1 levels and activity (PubMed:33108758)\nEndogenous repressor of isoform 1, interacts with, and antagonizes CHK1 to promote the S to G2/M phase transition","source":"project UniProt records20261017/18"},{"partner":"HELLS","hgnc":"HGNC:4861","core":true,"core_annotation":{"hgnc":"HGNC:4861","symbol_at_source":"HELLS","accession":"Q9NRZ9","function":"Chromatin remodeling","target":"chromatin","pmids":["14612388"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":157,"hub_weight":0.49147318718299043,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"ATP-dependent chromatin remodeler that regulates chromatin accessibility, DNA methylation, and histone modifications. It facilitates de novo DNA methylation at repetitive sequences and promotes transcriptional silencing via recruitment of DNA methyltransferases (DNMTs) and histone deacetylases (HDACs), contributing to heterochromatin formation and repression of transposable elements (PubMed:30307408). Also involved in DNA repair by recruiting DNA damage response mediators to double-strand breaks in heterochromatin, promoting homologous recombination via RBBP8/CtIP-dependent end resection (PubMed:22946062, PubMed:31802118). During meiosis, it is recruited by PRDM9 to recombination hotspots, aiding chromatin opening (PubMed:32001511). Through these diverse roles, is crucial for processes such as development, differentiation, and genomic stability (PubMed:22946062, PubMed:31802118). Involved in regulation of the expansion or survival of lymphoid cells (By similarity)","source":"project UniProt records20261017/18"},{"partner":"TAF9","hgnc":"HGNC:11542","core":true,"core_annotation":{"hgnc":"HGNC:11542","symbol_at_source":"TAF9","accession":"Q16594","function":"Histone chaperone","target":"DNA","pmids":["9674425"],"complexes":"PCAF, STAGA, CHD8, MLL2/3, MLL4/WBP7","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":152,"hub_weight":0.4975185951049946,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"The TFIID basal transcription factor complex plays a major role in the initiation of RNA polymerase II (Pol II)-dependent transcription (PubMed:33795473). TFIID recognizes and binds promoters with or without a TATA box via its subunit TBP, a TATA-box-binding protein, and promotes assembly of the pre-initiation complex (PIC) (PubMed:33795473). The TFIID complex consists of TBP and TBP-associated factors (TAFs), including TAF1, TAF2, TAF3, TAF4, TAF5, TAF6, TAF7, TAF8, TAF9, TAF10, TAF11, TAF12 and TAF13 (PubMed:33795473). TAF9 is also a component of the TBP-free TAFII complex (TFTC), the PCAF histone acetylase complex and the STAGA transcription coactivator-HAT complex (PubMed:15899866). TAF9 and its paralog TAF9B are involved in transcriptional activation as well as repression of distinct but overlapping sets of genes (PubMed:15899866). Essential for cell viability (PubMed:15899866). May have a role in gene regulation associated with apoptosis (PubMed:15899866)","source":"project UniProt records20261017/18"},{"partner":"USP22","hgnc":"HGNC:12621","core":true,"core_annotation":{"hgnc":"HGNC:12621","symbol_at_source":"USP22","accession":"Q9UPT9","function":"Histone modification write cofactor","target":"histone","pmids":["18469533"],"complexes":"SAGA","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":122,"hub_weight":0.5391638660171921,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Deubiquitinase that plays a role in several cellular processes including transcriptional regulation, cell cycle progression or innate immunity. As part of the transcription regulatory histone acetylation (HAT) complex SAGA, catalyzes the deubiquitination of both histones H2A and H2B, thereby acting as a transcriptional coactivator (PubMed:18206972, PubMed:18206973, PubMed:18469533). Recruited to specific gene promoters by activators such as MYC, where it is required for transcription. Facilitates cell-cycle progression by stabilizing CCNB1 and antagonizing its proteasome-mediated degradation in a cell cycle-specific manner (PubMed:27030811). Modulates cell cycle progression and apoptosis also by antagonizing TP53 transcriptional activation through deacetylase SIRT1 stabilization (PubMed:22542455). Plays multiple roles in immunity and inflammation. Participates in antiviral response by deubiquitinating the importin KPNA2, leading to IRF3 nuclear translocation and subsequent type I interferon production (PubMed:32130408). Acts as a central regulator of type III IFN signaling by negatively regulating STING1 activation and ubiquitination (PubMed:35933402). Inhibits NLRP3 inflammasome activation by promoting NLRP3 degradation through ATG5-dependent autophagy (By similarity). Deubiquitinates CD274 to induce its stabilization and thereby participates in maintenance of immune tolerance to self (PubMed:31399419). Controls necroptotic cell death by regulating RIPK3 phosphorylation and ubiquitination (PubMed:33369872). During bacterial infection, promotes pro-inflammatory response by targeting TRAF6 and removing its 'Lys-48'-linked polyubiquitination (By similarity)","source":"project UniProt records20261017/18"},{"partner":"TAF6L","hgnc":"HGNC:17305","core":true,"core_annotation":{"hgnc":"HGNC:17305","symbol_at_source":"TAF6L","accession":"Q9Y6J9","function":"Histone chaperone","target":"histone","pmids":["12601814"],"complexes":"PCAF, TFTC-HAT, STAGA","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":87,"hub_weight":0.604122093330177,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Functions as a component of the PCAF complex. The PCAF complex is capable of efficiently acetylating histones in a nucleosomal context. The PCAF complex could be considered as the human version of the yeast SAGA complex (Probable). With TAF5L, acts as an epigenetic regulator essential for somatic reprogramming. Regulates target genes through H3K9ac deposition and MYC recruitment which trigger MYC regulatory network to orchestrate gene expression programs to control embryonic stem cell state. Functions with MYC to activate target gene expression through RNA polymerase II pause release (By similarity)","source":"project UniProt records20261017/18"},{"partner":"TAF9B","hgnc":"HGNC:17306","core":true,"core_annotation":{"hgnc":"HGNC:17306","symbol_at_source":"TAF9B","accession":"Q9HBM6","function":"Histone chaperone","target":"histone","pmids":["15899866"],"complexes":"TFTC-HAT","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":106,"hub_weight":0.5661385170722979,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Essential for cell viability. TAF9 and TAF9B are involved in transcriptional activation as well as repression of distinct but overlapping sets of genes. May have a role in gene regulation associated with apoptosis. TAFs are components of the transcription factor IID (TFIID) complex, the TBP-free TAFII complex (TFTC), the PCAF histone acetylase complex and the STAGA transcription coactivator-HAT complex. TFIID or TFTC are essential for the regulation of RNA polymerase II-mediated transcription","source":"project UniProt records20261017/18"},{"partner":"USP36","hgnc":"HGNC:20062","core":true,"core_annotation":{"hgnc":"HGNC:20062","symbol_at_source":"USP36","accession":"Q9P275","function":"Histone modification write cofactor","target":"histone","pmids":["22622177"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":492,"hub_weight":0.3037283696153935,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus, nucleolus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Deubiquitinase essential for the regulation of nucleolar structure and function (PubMed:19208757, PubMed:22902402, PubMed:29273634). Required for cell and organism viability (PubMed:19208757, PubMed:22902402, PubMed:29273634). Plays an important role in ribosomal RNA processing and protein synthesis, which is mediated, at least in part, through deubiquitination of DHX33, NPM1 and FBL, regulating their protein stability (PubMed:19208757, PubMed:22902402, PubMed:29273634, PubMed:36912080). Functions as a transcriptional repressor by deubiquiting histone H2B at the promoters of genes critical for cellular differentiation, such as CDKN1A, thereby preventing histone H3 'Lys-4' trimethylation (H3K4) (PubMed:29274341). Specifically deubiquitinates MYC in the nucleolus, leading to prevent MYC degradation by the proteasome: acts by specifically interacting with isoform 3 of FBXW7 (FBW7gamma) in the nucleolus and counteracting ubiquitination of MYC by the SCF(FBW7) complex (PubMed:25775507). In contrast, it does not interact with isoform 1 of FBXW7 (FBW7alpha) in the nucleoplasm (PubMed:25775507). Interacts to and regulates the actions of E3 ubiquitin-protein ligase NEDD4L over substrates such as NTRK1, KCNQ2 and KCNQ3, affecting their expression an functions (PubMed:27445338). Deubiquitinates SOD2, regulates SOD2 protein stability (PubMed:21268071). Deubiquitinase activity is required to control selective autophagy activation by ubiquitinated proteins (PubMed:22622177). Promotes CEP63 stabilization through 'Lys-48'-linked deubiquitination leading to increased stability (PubMed:35989368). Acts as a SUMO ligase to promote EXOSC10 sumoylation critical for the nucleolar RNA exosome function in rRNA processing (PubMed:36912080). Binds to pre-rRNAs (PubMed:36912080)","source":"project UniProt records20261017/18"},{"partner":"DNAJC1","hgnc":"HGNC:20090","core":true,"core_annotation":{"hgnc":"HGNC:20090","symbol_at_source":"DNAJC1","accession":"Q96KC8","function":"Histone modification write cofactor, Histone modification erase cofactor","target":"histone","pmids":["16271702"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":198,"hub_weight":0.44901325506693723,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Endoplasmic reticulum membrane; Nucleus membrane; Microsome membrane","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"May modulate protein synthesis","source":"project UniProt records20261017/18"},{"partner":"TADA1","hgnc":"HGNC:30631","core":true,"core_annotation":{"hgnc":"HGNC:30631","symbol_at_source":"TADA1","accession":"Q96BN2","function":"Histone chaperone","target":"histone","pmids":["11564863"],"complexes":"STAGA","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":52,"hub_weight":0.7001400420140049,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Probably involved in transcriptional regulation","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"FAM219B":{"coreEvidence":[{"partner":"ELP2","hgnc":"HGNC:18248","core":true,"core_annotation":{"hgnc":"HGNC:18248","symbol_at_source":"ELP2","accession":"Q6IA86","function":"Histone modification write cofactor","target":"histone","pmids":["11818576"],"complexes":"Pol2 elongator","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":86,"hub_weight":0.6063390625908325,"quality":0.65,"programmes":["BioPlex"],"pmids":["26186194","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HCT116","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Component of the elongator complex which is required for multiple tRNA modifications, including mcm5U (5-methoxycarbonylmethyl uridine), mcm5s2U (5-methoxycarbonylmethyl-2-thiouridine), and ncm5U (5-carbamoylmethyl uridine) (PubMed:29332244). The elongator complex catalyzes the formation of carboxymethyluridine in the wobble base at position 34 in tRNAs (PubMed:29332244)","source":"project UniProt records20261017/18"},{"partner":"ELP3","hgnc":"HGNC:20696","core":true,"core_annotation":{"hgnc":"HGNC:20696","symbol_at_source":"ELP3","accession":"Q9H9T3","function":"Histone modification write","target":"histone","pmids":["11818576"],"complexes":"Pol2 elongator","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":80,"hub_weight":0.6201736729460423,"quality":0.65,"programmes":["BioPlex"],"pmids":["26186194","28514442","33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HCT116 colon carcinoma cell\", \"human-hct116\"]","IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HCT116","dataset_cell:HEK293T"],"partner_location":"Cytoplasm; Nucleus; Nucleus; Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic tRNA acetyltransferase subunit of the elongator complex which is required for multiple tRNA modifications, including mcm5U (5-methoxycarbonylmethyl uridine), mcm5s2U (5-methoxycarbonylmethyl-2-thiouridine), and ncm5U (5-carbamoylmethyl uridine) (PubMed:29415125). In the elongator complex, acts as a tRNA uridine(34) acetyltransferase by mediating formation of carboxymethyluridine in the wobble base at position 34 in tRNAs (By similarity). May also act as a protein lysine acetyltransferase by mediating acetylation of target proteins; such activity is however unclear in vivo and recent evidence suggests that ELP3 primarily acts as a tRNA acetyltransferase (PubMed:29415125). Not a major acetyltransferase of tubulin (PubMed:22153374). Involved in neurogenesis: regulates the migration and branching of projection neurons in the developing cerebral cortex, through a process depending on alpha-tubulin acetylation (PubMed:19185337). Required for acetylation of GJA1 in the developing cerebral cortex (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"PRR22":{"coreEvidence":[{"partner":"HDGF","hgnc":"HGNC:4856","core":true,"core_annotation":{"hgnc":"HGNC:4856","symbol_at_source":"HDGF","accession":"P51858","function":"Chromatin remodeling, TF","target":"DNA","pmids":["18331345","17974029"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":273,"hub_weight":0.39344473768231686,"quality":0.65,"programmes":["pubmed:34535262"],"pmids":["34535262"],"assays":["crosslink"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Secreted, extracellular exosome; Nucleus; Cytoplasm; Secreted, extracellular exosome; Nucleus; Cytoplasm; Secreted, extracellular exosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Acts as a transcriptional repressor (PubMed:17974029). Has mitogenic activity for fibroblasts (PubMed:11751870, PubMed:26845719). Heparin-binding protein (PubMed:15491618)\nDoes not have mitogenic activity for fibroblasts (PubMed:26845719). Does not bind heparin (PubMed:26845719)\nHas mitogenic activity for fibroblasts (PubMed:26845719). Heparin-binding protein (PubMed:26845719)","source":"project UniProt records20261017/18"},{"partner":"SMYD1","hgnc":"HGNC:20986","core":true,"core_annotation":{"hgnc":"HGNC:20986","symbol_at_source":"SMYD1","accession":"Q8NB12","function":"Histone modification write","target":"histone","pmids":["22498752"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":37,"hub_weight":0.7580980435789034,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Methylates histone H3 at 'Lys-4' (H3K4me), seems able to perform both mono-, di-, and trimethylation. Acts as a transcriptional repressor. Essential for cardiomyocyte differentiation and cardiac morphogenesis","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"ZC2HC1C":{"coreEvidence":[{"partner":"KAT5","hgnc":"HGNC:5275","core":true,"core_annotation":{"hgnc":"HGNC:5275","symbol_at_source":"KAT5","accession":"Q92993","function":"Histone modification write","target":"histone","pmids":["10096020"],"complexes":"SWR, NuA4, Piccolo_NuA4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":337,"hub_weight":0.3594425773447947,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm; Chromosome, centromere, kinetochore; Cytoplasm, cytoskeleton, spindle pole; Nucleus, nucleolus; Cytoplasm, perinuclear region; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of the NuA4 histone acetyltransferase complex, a multiprotein complex involved in transcriptional activation of select genes principally by acetylation of nucleosomal histones H2A and H4 (PubMed:12776177, PubMed:14966270, PubMed:15042092, PubMed:15121871, PubMed:15310756, PubMed:16387653, PubMed:19909775, PubMed:25865756, PubMed:27153538, PubMed:29174981, PubMed:29335245, PubMed:32822602, PubMed:33076429). Histone acetylation alters nucleosome-DNA interactions and promotes interaction of the modified histones with other proteins which positively regulate transcription (PubMed:12776177, PubMed:14966270, PubMed:15042092, PubMed:15121871, PubMed:15310756). The NuA4 histone acetyltransferase complex is required for the activation of transcriptional programs associated with proto-oncogene mediated growth induction, tumor suppressor mediated growth arrest and replicative senescence, apoptosis, and DNA repair (PubMed:17709392, PubMed:19783983, PubMed:32832608). The NuA4 complex plays a direct role in repair of DNA double-strand breaks (DSBs) by promoting homologous recombination (HR): the complex inhibits TP53BP1 binding to chromatin via MBTD1, which recognizes and binds histone H4 trimethylated at 'Lys-20' (H4K20me), and KAT5 that catalyzes acetylation of 'Lys-15' of histone H2A (H2AK15ac), thereby blocking the ubiquitination mark required for TP53BP1 localization at DNA breaks (PubMed:27153538, PubMed:32832608). Also involved in DSB repair by mediating acetylation of 'Lys-5' of histone H2AX (H2AXK5ac), promoting NBN/NBS1 assembly at the sites of DNA damage (PubMed:17709392, PubMed:26438602). The NuA4 complex plays a key role in hematopoietic stem cell maintenance and is required to maintain acetylated H2A.Z/H2AZ1 at MYC target genes (By similarity). The NuA4 complex is also required for spermatid development by promoting acetylation of histones: histone hyperacetylation is required for histone replacement during the transition from round to elongating spermatids (By similarity). Component of a SWR1-like complex that specifically mediates the removal of histone H2A.Z/H2AZ1 from the nucleosome (PubMed:24463511). Also acetylates non-histone proteins, such as BMAL1, ATM, AURKB, CHKA, CGAS, ERCC4/XPF, LPIN1, TP53/p53, NDC80/HEC1, NR1D2, RAN, SOX4, FOXP3, SQSTM1, ULK1 and RUBCNL/Pacer (PubMed:16141325, PubMed:17189187, PubMed:17360565, PubMed:17996965, PubMed:24835996, PubMed:26829474, PubMed:29040603, PubMed:30409912, PubMed:30704899, PubMed:31857589, PubMed:32034146, PubMed:32817552, PubMed:34077757). Directly acetylates and activates ATM (PubMed:16141325). Promotes nucleotide excision repair (NER) by mediating acetylation of ERCC4/XPF, thereby promoting formation of the ERCC4-ERCC1 complex (PubMed:32034146). Relieves NR1D2-mediated inhibition of APOC3 expression by acetylating NR1D2 (PubMed:17996965). Acts as a regulator of regulatory T-cells (Treg) by catalyzing FOXP3 acetylation, thereby promoting FOXP3 transcriptional repressor activity (PubMed:17360565, PubMed:24835996). Involved in skeletal myoblast differentiation by mediating acetylation of SOX4 (PubMed:26291311). Catalyzes acetylation of APBB1/FE65, increasing its transcription activator activity (PubMed:33938178). Promotes transcription elongation during the activation phase of the circadian cycle by catalyzing acetylation of BMAL1, promoting elongation of circadian transcripts (By similarity). Together with GSK3 (GSK3A or GSK3B), acts as a regulator of autophagy: phosphorylated at Ser-86 by GSK3 under starvation conditions, leading to activate acetyltransferase activity and promote acetylation of key autophagy regulators, such as ULK1 and RUBCNL/Pacer (PubMed:30704899). Acts as a regulator of the cGAS-STING innate antiviral response by catalyzing acetylation the N-terminus of CGAS, thereby promoting CGAS DNA-binding and activation (PubMed:32817552). Also regulates lipid metabolism by mediating acetylation of CHKA or LPIN1 (PubMed:34077757). Promotes lipolysis of lipid droplets following glucose deprivation by mediating acetylation of isoform 1 of CHKA, thereby promoting monomerization of CHKA and its conversion into a tyrosine-protein kinase (PubMed:34077757). Acts as a regulator of fatty-acid-induced triacylglycerol synthesis by catalyzing acetylation of LPIN1, thereby promoting the synthesis of diacylglycerol (PubMed:29765047). In addition to protein acetyltransferase, can use different acyl-CoA substrates, such as (2E)-butenoyl-CoA (crotonyl-CoA), S-lactoyl-CoA (lactyl-CoA) and 2-hydroxyisobutanoyl-CoA (2-hydroxyisobutyryl-CoA), and is able to mediate protein crotonylation, lactylation and 2-hydroxyisobutyrylation, respectively (PubMed:29192674, PubMed:34608293, PubMed:38961290). Acts as a key regulator of chromosome segregation and kinetochore-microtubule attachment during mitosis by mediating acetylation or crotonylation of target proteins (PubMed:26829474, PubMed:29040603, PubMed:30409912, PubMed:34608293). Catalyzes acetylation of AURKB at kinetochores, increasing AURKB activity and promoting accurate chromosome segregation in mitosis (PubMed:26829474). Acetylates RAN during mitosis, promoting microtubule assembly at mitotic chromosomes (PubMed:29040603). Acetylates NDC80/HEC1 during mitosis, promoting robust kinetochore-microtubule attachment (PubMed:30409912). Catalyzes crotonylation of MAPRE1/EB1, thereby ensuring accurate spindle positioning in mitosis (PubMed:34608293). Catalyzes lactylation of NBN/NBS1 in response to DNA damage, thereby promoting DNA double-strand breaks (DSBs) via homologous recombination (HR) (PubMed:38961290)\n(Microbial infection) Catalyzes the acetylation of flavivirus NS3 protein to modulate their RNA-binding and -unwinding activities leading to facilitate viral replication","source":"project UniProt records20261017/18"},{"partner":"NEK6","hgnc":"HGNC:7749","core":true,"core_annotation":{"hgnc":"HGNC:7749","symbol_at_source":"NEK6","accession":"Q9HC98","function":"Histone modification write","target":"histone","pmids":["12054534"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":119,"hub_weight":0.5439282932204211,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Cytoplasm; Nucleus; Nucleus speckle; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, spindle pole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Protein kinase which plays an important role in mitotic cell cycle progression (PubMed:11516946, PubMed:14563848). Required for chromosome segregation at metaphase-anaphase transition, robust mitotic spindle formation and cytokinesis (PubMed:19414596). Phosphorylates ATF4, CIRSR, PTN, RAD26L, RBBP6, RPS7, RPS6KB1, TRIP4, STAT3 and histones H1 and H3 (PubMed:12054534, PubMed:20873783). Phosphorylates KIF11 to promote mitotic spindle formation (PubMed:19001501). Involved in G2/M phase cell cycle arrest induced by DNA damage (PubMed:18728393). Inhibition of activity results in apoptosis. May contribute to tumorigenesis by suppressing p53/TP53-induced cancer cell senescence (PubMed:21099361). Phosphorylates EML4 at 'Ser-144', promoting its dissociation from microtubules during mitosis which is required for efficient chromosome congression (PubMed:31409757)","source":"project UniProt records20261017/18"},{"partner":"PRKAB2","hgnc":"HGNC:9379","core":true,"core_annotation":{"hgnc":"HGNC:9379","symbol_at_source":"PRKAB2","accession":"O43741","function":"Histone modification write cofactor","target":"histone","pmids":["20647423"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":146,"hub_weight":0.5050762722761054,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"","partner_has_nuclear_annotation":false,"partner_location_assessed":false,"function":"Non-catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism. In response to reduction of intracellular ATP levels, AMPK activates energy-producing pathways and inhibits energy-consuming processes: inhibits protein, carbohydrate and lipid biosynthesis, as well as cell growth and proliferation. AMPK acts via direct phosphorylation of metabolic enzymes, and by longer-term effects via phosphorylation of transcription regulators. Also acts as a regulator of cellular polarity by remodeling the actin cytoskeleton; probably by indirectly activating myosin. Beta non-catalytic subunit acts as a scaffold on which the AMPK complex assembles, via its C-terminus that bridges alpha (PRKAA1 or PRKAA2) and gamma subunits (PRKAG1, PRKAG2 or PRKAG3)","source":"project UniProt records20261017/18"},{"partner":"TRIM27","hgnc":"HGNC:9975","core":true,"core_annotation":{"hgnc":"HGNC:9975","symbol_at_source":"TRIM27","accession":"P14373","function":"Histone modification erase cofactor","target":"#","pmids":["19351825"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":414,"hub_weight":0.32826608214930636,"quality":0.75,"programmes":["CCSB_binary_maps","pubmed:21516116"],"pmids":["21516116","25416956"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body; Early endosome; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that mediates ubiquitination of various substrates and thereby plays a role in diffent processes including proliferation, innate immunity, apoptosis, immune response or autophagy (PubMed:22829933, PubMed:24144979, PubMed:29688809, PubMed:36111389). Ubiquitinates PIK3C2B and inhibits its activity by mediating the formation of 'Lys-48'-linked polyubiquitin chains; the function inhibits CD4 T-cell activation. Acts as a regulator of retrograde transport: together with MAGEL2, mediates the formation of 'Lys-63'-linked polyubiquitin chains at 'Lys-220' of WASHC1, leading to promote endosomal F-actin assembly (PubMed:23452853). Has a transcriptional repressor activity by cooperating with EPC1. Induces apoptosis by activating Jun N-terminal kinase and p38 kinase and also increases caspase-3-like activity independently of mitochondrial events. May function in male germ cell development. Has DNA-binding activity and preferentially bound to double-stranded DNA. Forms a complex with and ubiquitinates the ubiquitin-specific protease USP7, which in turn deubiquitinates RIPK1 resulting in the positive regulation of TNF-induced apoptosis (PubMed:24144979). In addition, acts with USP7 or PTPN11 as an inhibitor of the antiviral signaling pathway by promoting kinase TBK1 ubiquitination and degradation (PubMed:26358190, PubMed:29688809). Acts as a negative regulator of NOD2 signaling by mediating ubiquitination of NOD2, promoting its degradation by the proteasome (PubMed:22829933). Alternatively, facilitates mitophagy via stabilization of active TBK1 (PubMed:36111389). Negatively regulates autophagy flux under basal conditions by directly polyubiquitinating ULK1 (PubMed:35670107). During starvation-induced autophagy, catalyzes non-degradative ubiquitination of the kinase STK38L promoting its activation and phosphorylation of ULK1 leading to its ubiquitination and degradation to restrain the amplitude and duration of autophagy (PubMed:35670107)\n(Microbial infection) Positively regulates hepatitis C virus replication by suppressing type I IFN response during infection","source":"project UniProt records20261017/18"},{"partner":"SMARCD1","hgnc":"HGNC:11106","core":true,"core_annotation":{"hgnc":"HGNC:11106","symbol_at_source":"SMARCD1","accession":"Q96GM5","function":"Chromatin remodeling","target":"chromatin","pmids":["12917342"],"complexes":"BAF, nBAF, npBAF, PBAF, SWI/SNF_Brg1(I), SWI/SNF_Brm, SWI/SNF-like_EPAFa, WINAC, SWI/SNF-like EPAFB, SWI/SNF BRM-BRG1","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":285,"hub_weight":0.3863337046431279,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in transcriptional activation and repression of select genes by chromatin remodeling (alteration of DNA-nucleosome topology). Component of SWI/SNF chromatin remodeling complexes that carry out key enzymatic activities, changing chromatin structure by altering DNA-histone contacts within a nucleosome in an ATP-dependent manner (PubMed:29374058, PubMed:8804307). Belongs to the neural progenitors-specific chromatin remodeling complex (npBAF complex) and the neuron-specific chromatin remodeling complex (nBAF complex). During neural development a switch from a stem/progenitor to a postmitotic chromatin remodeling mechanism occurs as neurons exit the cell cycle and become committed to their adult state. The transition from proliferating neural stem/progenitor cells to postmitotic neurons requires a switch in subunit composition of the npBAF and nBAF complexes. As neural progenitors exit mitosis and differentiate into neurons, npBAF complexes which contain ACTL6A/BAF53A and PHF10/BAF45A, are exchanged for homologous alternative ACTL6B/BAF53B and DPF1/BAF45B or DPF3/BAF45C subunits in neuron-specific complexes (nBAF). The npBAF complex is essential for the self-renewal/proliferative capacity of the multipotent neural stem cells. The nBAF complex along with CREST plays a role regulating the activity of genes essential for dendrite growth (By similarity). Has a strong influence on vitamin D-mediated transcriptional activity from an enhancer vitamin D receptor element (VDRE). May be a link between mammalian SWI-SNF-like chromatin remodeling complexes and the vitamin D receptor (VDR) heterodimer (PubMed:14698202). Mediates critical interactions between nuclear receptors and the BRG1/SMARCA4 chromatin-remodeling complex for transactivation (PubMed:12917342). Interacts with AKIRIN2 (By similarity)","source":"project UniProt records20261017/18"},{"partner":"BANP","hgnc":"HGNC:13450","core":true,"core_annotation":{"hgnc":"HGNC:13450","symbol_at_source":"BANP","accession":"Q8N9N5","function":"Histone modification write","target":"histone","pmids":["16166625"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":193,"hub_weight":0.45360921162651446,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["25416956"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Nucleus speckle; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Controls V(D)J recombination during T-cell development by repressing T-cell receptor (TCR) beta enhancer function (By similarity). Binds to scaffold/matrix attachment region beta (S/MARbeta), an ATC-rich DNA sequence located upstream of the TCR beta enhancer (By similarity). Represses cyclin D1 transcription by recruiting HDAC1 to its promoter, thereby diminishing H3K9ac, H3S10ph and H4K8ac levels (PubMed:16166625). Promotes TP53 activation, which causes cell cycle arrest (By similarity). Plays a role in the regulation of alternative splicing (PubMed:26080397). Binds to CD44 pre-mRNA and negatively regulates the inclusion of CD44 proximal variable exons v2-v6 but has no effect on distal variable exons v7-v10 (PubMed:26080397)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"KIAA1549L":{"coreEvidence":[{"partner":"PARP3","hgnc":"HGNC:273","core":true,"core_annotation":{"hgnc":"HGNC:273","symbol_at_source":"PARP3","accession":"Q9Y6F1","function":"Polycomb group (PcG) protein","target":"#","pmids":["16924674"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":209,"hub_weight":0.4393747751637468,"quality":0.4,"programmes":["pubmed:40057523"],"pmids":["40057523"],"assays":["proximity_label"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome, centriole","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Mono-ADP-ribosyltransferase that mediates mono-ADP-ribosylation of target proteins and plays a key role in the response to DNA damage (PubMed:16924674, PubMed:19354255, PubMed:20064938, PubMed:21211721, PubMed:21270334, PubMed:23742272, PubMed:24598253, PubMed:25043379, PubMed:28447610). Mediates mono-ADP-ribosylation of glutamate, aspartate or lysine residues on target proteins (PubMed:20064938, PubMed:25043379). In contrast to PARP1 and PARP2, it is not able to mediate poly-ADP-ribosylation (PubMed:25043379). Involved in DNA repair by mediating mono-ADP-ribosylation of a limited number of acceptor proteins involved in chromatin architecture and in DNA metabolism, such as histone H2B, XRCC5 and XRCC6 (PubMed:16924674, PubMed:24598253). ADP-ribosylation follows DNA damage and appears as an obligatory step in a detection/signaling pathway leading to the reparation of DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Involved in single-strand break repair by catalyzing mono-ADP-ribosylation of histone H2B on 'Glu-2' (H2BE2ADPr) of nucleosomes containing nicked DNA (PubMed:27530147). Cooperates with the XRCC5-XRCC6 (Ku80-Ku70) heterodimer to limit end-resection thereby promoting accurate NHEJ (PubMed:24598253). Suppresses G-quadruplex (G4) structures in response to DNA damage (PubMed:28447610). Associates with a number of DNA repair factors and is involved in the response to exogenous and endogenous DNA strand breaks (PubMed:16924674, PubMed:21211721, PubMed:21270334). Together with APLF, promotes the retention of the LIG4-XRCC4 complex on chromatin and accelerate DNA ligation during non-homologous end-joining (NHEJ) (PubMed:21211721). May link the DNA damage surveillance network to the mitotic fidelity checkpoint (PubMed:16924674). Acts as a negative regulator of immunoglobulin class switch recombination, probably by controlling the level of AICDA /AID on the chromatin (By similarity). In addition to proteins, also able to ADP-ribosylate DNA: mediates DNA mono-ADP-ribosylation of DNA strand break termini via covalent addition of a single ADP-ribose moiety to a 5'- or 3'-terminal phosphate residues in DNA containing multiple strand breaks (PubMed:29361132, PubMed:29520010)","source":"project UniProt records20261017/18"},{"partner":"USP7","hgnc":"HGNC:12630","core":true,"core_annotation":{"hgnc":"HGNC:12630","symbol_at_source":"USP7","accession":"Q93009","function":"Histone modification erase, DNA modification cofactor","target":"histone, DNA","pmids":["15749019"],"complexes":"BCOR","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":684,"hub_weight":0.2609978754859403,"quality":1,"programmes":["pubmed:36243803"],"pmids":["36243803"],"assays":["reconstituted"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Hydrolase that deubiquitinates target proteins such as ARMC5, FOXO4, DEPTOR, KAT5, p53/TP53, MDM2, ERCC6, DNMT1, UHRF1, PTEN, KMT2E/MLL5 and DAXX (PubMed:11923872, PubMed:15053880, PubMed:16964248, PubMed:18716620, PubMed:25283148, PubMed:25865756, PubMed:26678539, PubMed:28655758, PubMed:33544460, PubMed:35216969). Together with DAXX, prevents MDM2 self-ubiquitination and enhances the E3 ligase activity of MDM2 towards p53/TP53, thereby promoting p53/TP53 ubiquitination and proteasomal degradation (PubMed:15053880, PubMed:16845383, PubMed:18566590, PubMed:20153724). Deubiquitinates p53/TP53, preventing degradation of p53/TP53, and enhances p53/TP53-dependent transcription regulation, cell growth repression and apoptosis (PubMed:25283148). Deubiquitinates p53/TP53 and MDM2 and strongly stabilizes p53/TP53 even in the presence of excess MDM2, and also induces p53/TP53-dependent cell growth repression and apoptosis (PubMed:11923872, PubMed:26786098). Deubiquitination of FOXO4 in presence of hydrogen peroxide is not dependent on p53/TP53 and inhibits FOXO4-induced transcriptional activity (PubMed:16964248). In association with DAXX, is involved in the deubiquitination and translocation of PTEN from the nucleus to the cytoplasm, both processes that are counteracted by PML (PubMed:18716620). Deubiquitinates KMT2E/MLL5 preventing KMT2E/MLL5 proteasomal-mediated degradation (PubMed:26678539). Involved in cell proliferation during early embryonic development. Involved in transcription-coupled nucleotide excision repair (TC-NER) in response to UV damage: recruited to DNA damage sites following interaction with KIAA1530/UVSSA and promotes deubiquitination of ERCC6, preventing UV-induced degradation of ERCC6 (PubMed:22466611, PubMed:22466612). Involved in maintenance of DNA methylation via its interaction with UHRF1 and DNMT1: acts by mediating deubiquitination of UHRF1 and DNMT1, preventing their degradation and promoting DNA methylation by DNMT1 (PubMed:21745816, PubMed:22411829). Deubiquitinates alkylation repair enzyme ALKBH3. OTUD4 recruits USP7 and USP9X to stabilize ALKBH3, thereby promoting the repair of alkylated DNA lesions (PubMed:25944111). Acts as a chromatin regulator via its association with the Polycomb group (PcG) multiprotein PRC1-like complex; may act by deubiquitinating components of the PRC1-like complex (PubMed:20601937). Able to mediate deubiquitination of histone H2B; it is however unsure whether this activity takes place in vivo (PubMed:20601937). Exhibits a preference towards 'Lys-48'-linked ubiquitin chains (PubMed:22689415). Increases regulatory T-cells (Treg) suppressive capacity by deubiquitinating and stabilizing the transcription factor FOXP3 which is crucial for Treg cell function (PubMed:23973222). Plays a role in the maintenance of the circadian clock periodicity via deubiquitination and stabilization of the CRY1 and CRY2 proteins (PubMed:27123980). Deubiquitinates REST, thereby stabilizing REST and promoting the maintenance of neural progenitor cells (PubMed:21258371). Deubiquitinates SIRT7, inhibiting SIRT7 histone deacetylase activity and regulating gluconeogenesis (PubMed:28655758). Involved in the regulation of WASH-dependent actin polymerization at the surface of endosomes and the regulation of endosomal protein recycling (PubMed:26365382). It maintains optimal WASH complex activity and precise F-actin levels via deubiquitination of TRIM27 and WASHC1 (PubMed:26365382). Mediates the deubiquitination of phosphorylated DEPTOR, promoting its stability and leading to decreased mTORC1 signaling (PubMed:35216969). Deubiquitinates H2AB1, H2BC4 and H2BC22 (By similarity)\n(Microbial infection) Contributes to the overall stabilization and trans-activation capability of the herpesvirus 1 trans-acting transcriptional protein ICP0/VMW110 during HSV-1 infection\n(Microbial infection) Upon infection with Epstein-Barr virus, the interaction with viral EBNA1 increases the association of USP7 with PML proteins, which is required for the polyubiquitylation and degradation of PML","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"SCRN2":{"coreEvidence":[{"partner":"CTBP1","hgnc":"HGNC:2494","core":true,"core_annotation":{"hgnc":"HGNC:2494","symbol_at_source":"CTBP1","accession":"Q13363","function":"Chromatin remodeling","target":"chromatin","pmids":["21102443"],"complexes":"LSD-CoREST","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":575,"hub_weight":0.282842712474619,"quality":0.65,"programmes":["pubmed:36688959"],"pmids":["36688959"],"assays":["capture_association"],"contexts":[],"partner_location":"Cytoplasm; Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Corepressor targeting diverse transcription regulators such as GLIS2 or BCL6. Has dehydrogenase activity. Involved in controlling the equilibrium between tubular and stacked structures in the Golgi complex. Functions in brown adipose tissue (BAT) differentiation","source":"project UniProt records20261017/18"},{"partner":"KAT5","hgnc":"HGNC:5275","core":true,"core_annotation":{"hgnc":"HGNC:5275","symbol_at_source":"KAT5","accession":"Q92993","function":"Histone modification write","target":"histone","pmids":["10096020"],"complexes":"SWR, NuA4, Piccolo_NuA4","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":337,"hub_weight":0.3594425773447947,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm; Chromosome, centromere, kinetochore; Cytoplasm, cytoskeleton, spindle pole; Nucleus, nucleolus; Cytoplasm, perinuclear region; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Catalytic subunit of the NuA4 histone acetyltransferase complex, a multiprotein complex involved in transcriptional activation of select genes principally by acetylation of nucleosomal histones H2A and H4 (PubMed:12776177, PubMed:14966270, PubMed:15042092, PubMed:15121871, PubMed:15310756, PubMed:16387653, PubMed:19909775, PubMed:25865756, PubMed:27153538, PubMed:29174981, PubMed:29335245, PubMed:32822602, PubMed:33076429). Histone acetylation alters nucleosome-DNA interactions and promotes interaction of the modified histones with other proteins which positively regulate transcription (PubMed:12776177, PubMed:14966270, PubMed:15042092, PubMed:15121871, PubMed:15310756). The NuA4 histone acetyltransferase complex is required for the activation of transcriptional programs associated with proto-oncogene mediated growth induction, tumor suppressor mediated growth arrest and replicative senescence, apoptosis, and DNA repair (PubMed:17709392, PubMed:19783983, PubMed:32832608). The NuA4 complex plays a direct role in repair of DNA double-strand breaks (DSBs) by promoting homologous recombination (HR): the complex inhibits TP53BP1 binding to chromatin via MBTD1, which recognizes and binds histone H4 trimethylated at 'Lys-20' (H4K20me), and KAT5 that catalyzes acetylation of 'Lys-15' of histone H2A (H2AK15ac), thereby blocking the ubiquitination mark required for TP53BP1 localization at DNA breaks (PubMed:27153538, PubMed:32832608). Also involved in DSB repair by mediating acetylation of 'Lys-5' of histone H2AX (H2AXK5ac), promoting NBN/NBS1 assembly at the sites of DNA damage (PubMed:17709392, PubMed:26438602). The NuA4 complex plays a key role in hematopoietic stem cell maintenance and is required to maintain acetylated H2A.Z/H2AZ1 at MYC target genes (By similarity). The NuA4 complex is also required for spermatid development by promoting acetylation of histones: histone hyperacetylation is required for histone replacement during the transition from round to elongating spermatids (By similarity). Component of a SWR1-like complex that specifically mediates the removal of histone H2A.Z/H2AZ1 from the nucleosome (PubMed:24463511). Also acetylates non-histone proteins, such as BMAL1, ATM, AURKB, CHKA, CGAS, ERCC4/XPF, LPIN1, TP53/p53, NDC80/HEC1, NR1D2, RAN, SOX4, FOXP3, SQSTM1, ULK1 and RUBCNL/Pacer (PubMed:16141325, PubMed:17189187, PubMed:17360565, PubMed:17996965, PubMed:24835996, PubMed:26829474, PubMed:29040603, PubMed:30409912, PubMed:30704899, PubMed:31857589, PubMed:32034146, PubMed:32817552, PubMed:34077757). Directly acetylates and activates ATM (PubMed:16141325). Promotes nucleotide excision repair (NER) by mediating acetylation of ERCC4/XPF, thereby promoting formation of the ERCC4-ERCC1 complex (PubMed:32034146). Relieves NR1D2-mediated inhibition of APOC3 expression by acetylating NR1D2 (PubMed:17996965). Acts as a regulator of regulatory T-cells (Treg) by catalyzing FOXP3 acetylation, thereby promoting FOXP3 transcriptional repressor activity (PubMed:17360565, PubMed:24835996). Involved in skeletal myoblast differentiation by mediating acetylation of SOX4 (PubMed:26291311). Catalyzes acetylation of APBB1/FE65, increasing its transcription activator activity (PubMed:33938178). Promotes transcription elongation during the activation phase of the circadian cycle by catalyzing acetylation of BMAL1, promoting elongation of circadian transcripts (By similarity). Together with GSK3 (GSK3A or GSK3B), acts as a regulator of autophagy: phosphorylated at Ser-86 by GSK3 under starvation conditions, leading to activate acetyltransferase activity and promote acetylation of key autophagy regulators, such as ULK1 and RUBCNL/Pacer (PubMed:30704899). Acts as a regulator of the cGAS-STING innate antiviral response by catalyzing acetylation the N-terminus of CGAS, thereby promoting CGAS DNA-binding and activation (PubMed:32817552). Also regulates lipid metabolism by mediating acetylation of CHKA or LPIN1 (PubMed:34077757). Promotes lipolysis of lipid droplets following glucose deprivation by mediating acetylation of isoform 1 of CHKA, thereby promoting monomerization of CHKA and its conversion into a tyrosine-protein kinase (PubMed:34077757). Acts as a regulator of fatty-acid-induced triacylglycerol synthesis by catalyzing acetylation of LPIN1, thereby promoting the synthesis of diacylglycerol (PubMed:29765047). In addition to protein acetyltransferase, can use different acyl-CoA substrates, such as (2E)-butenoyl-CoA (crotonyl-CoA), S-lactoyl-CoA (lactyl-CoA) and 2-hydroxyisobutanoyl-CoA (2-hydroxyisobutyryl-CoA), and is able to mediate protein crotonylation, lactylation and 2-hydroxyisobutyrylation, respectively (PubMed:29192674, PubMed:34608293, PubMed:38961290). Acts as a key regulator of chromosome segregation and kinetochore-microtubule attachment during mitosis by mediating acetylation or crotonylation of target proteins (PubMed:26829474, PubMed:29040603, PubMed:30409912, PubMed:34608293). Catalyzes acetylation of AURKB at kinetochores, increasing AURKB activity and promoting accurate chromosome segregation in mitosis (PubMed:26829474). Acetylates RAN during mitosis, promoting microtubule assembly at mitotic chromosomes (PubMed:29040603). Acetylates NDC80/HEC1 during mitosis, promoting robust kinetochore-microtubule attachment (PubMed:30409912). Catalyzes crotonylation of MAPRE1/EB1, thereby ensuring accurate spindle positioning in mitosis (PubMed:34608293). Catalyzes lactylation of NBN/NBS1 in response to DNA damage, thereby promoting DNA double-strand breaks (DSBs) via homologous recombination (HR) (PubMed:38961290)\n(Microbial infection) Catalyzes the acetylation of flavivirus NS3 protein to modulate their RNA-binding and -unwinding activities leading to facilitate viral replication","source":"project UniProt records20261017/18"},{"partner":"MAPKAPK3","hgnc":"HGNC:6888","core":true,"core_annotation":{"hgnc":"HGNC:6888","symbol_at_source":"MAPKAPK3","accession":"Q16644","function":"Chromatin remodeling","target":"chromatin","pmids":["15563468"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":51,"hub_weight":0.7035975447302919,"quality":0.35,"programmes":["pubmed:35831314"],"pmids":["35831314"],"assays":["cofractionation"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Stress-activated serine/threonine-protein kinase involved in cytokines production, endocytosis, cell migration, chromatin remodeling and transcriptional regulation. Following stress, it is phosphorylated and activated by MAP kinase p38-alpha/MAPK14, leading to phosphorylation of substrates. Phosphorylates serine in the peptide sequence, Hyd-X-R-X(2)-S, where Hyd is a large hydrophobic residue. MAPKAPK2 and MAPKAPK3, share the same function and substrate specificity, but MAPKAPK3 kinase activity and level in protein expression are lower compared to MAPKAPK2. Phosphorylates HSP27/HSPB1, KRT18, KRT20, RCSD1, RPS6KA3, TAB3 and TTP/ZFP36. Mediates phosphorylation of HSP27/HSPB1 in response to stress, leading to dissociate HSP27/HSPB1 from large small heat-shock protein (sHsps) oligomers and impair their chaperone activities and ability to protect against oxidative stress effectively. Involved in inflammatory response by regulating tumor necrosis factor (TNF) and IL6 production post-transcriptionally: acts by phosphorylating AU-rich elements (AREs)-binding proteins, such as TTP/ZFP36, leading to regulate the stability and translation of TNF and IL6 mRNAs. Phosphorylation of TTP/ZFP36, a major post-transcriptional regulator of TNF, promotes its binding to 14-3-3 proteins and reduces its ARE mRNA affinity leading to inhibition of dependent degradation of ARE-containing transcript. Involved in toll-like receptor signaling pathway (TLR) in dendritic cells: required for acute TLR-induced macropinocytosis by phosphorylating and activating RPS6KA3. Also acts as a modulator of Polycomb-mediated repression","source":"project UniProt records20261017/18"}],"near_known_relatives":[{"symbol":"SCRN1","accession":"Q12765","identity":0.517,"qcov":0.958,"tcov":0.969,"domain_context":"shared_family_context","structure_qualified":"True","function_pmids":[],"function":"Regulates exocytosis in mast cells. Increases both the extent of secretion and the sensitivity of mast cells to stimulation with calcium (By similarity)","member_mechanism_evidence_available":false}]},"TCEANC":{"coreEvidence":[{"partner":"BRCA1","hgnc":"HGNC:1100","core":true,"core_annotation":{"hgnc":"HGNC:1100","symbol_at_source":"BRCA1","accession":"P38398","function":"Histone modification write cofactor, TF","target":"DNA","pmids":["20820192"],"complexes":"BRCC, BRCA1-A","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":965,"hub_weight":0.22194838080923765,"quality":0.75,"programmes":["pubmed:25184681"],"pmids":["25184681"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Cytoplasm; Cytoplasm; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that specifically mediates the formation of 'Lys-6'-linked polyubiquitin chains and plays a central role in DNA repair by facilitating cellular responses to DNA damage (PubMed:10500182, PubMed:12887909, PubMed:12890688, PubMed:14976165, PubMed:16818604, PubMed:17525340, PubMed:19261748). It is unclear whether it also mediates the formation of other types of polyubiquitin chains (PubMed:12890688). The BRCA1-BARD1 heterodimer coordinates a diverse range of cellular pathways such as DNA damage repair, ubiquitination and transcriptional regulation to maintain genomic stability (PubMed:12890688, PubMed:14976165, PubMed:20351172). Regulates centrosomal microtubule nucleation (PubMed:18056443). Required for appropriate cell cycle arrests after ionizing irradiation in both the S-phase and the G2 phase of the cell cycle (PubMed:10724175, PubMed:11836499, PubMed:12183412, PubMed:19261748). Required for FANCD2 targeting to sites of DNA damage (PubMed:12887909). Inhibits lipid synthesis by binding to inactive phosphorylated ACACA and preventing its dephosphorylation (PubMed:16326698). Contributes to homologous recombination repair (HRR) via its direct interaction with PALB2, fine-tunes recombinational repair partly through its modulatory role in the PALB2-dependent loading of BRCA2-RAD51 repair machinery at DNA breaks (PubMed:19369211). Component of the BRCA1-RBBP8 complex which regulates CHEK1 activation and controls cell cycle G2/M checkpoints on DNA damage via BRCA1-mediated ubiquitination of RBBP8 (PubMed:16818604). Acts as a transcriptional activator (PubMed:20160719)","source":"project UniProt records20261017/18"},{"partner":"TRIM27","hgnc":"HGNC:9975","core":true,"core_annotation":{"hgnc":"HGNC:9975","symbol_at_source":"TRIM27","accession":"P14373","function":"Histone modification erase cofactor","target":"#","pmids":["19351825"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":414,"hub_weight":0.32826608214930636,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Nucleus, PML body; Early endosome; Mitochondrion","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"E3 ubiquitin-protein ligase that mediates ubiquitination of various substrates and thereby plays a role in diffent processes including proliferation, innate immunity, apoptosis, immune response or autophagy (PubMed:22829933, PubMed:24144979, PubMed:29688809, PubMed:36111389). Ubiquitinates PIK3C2B and inhibits its activity by mediating the formation of 'Lys-48'-linked polyubiquitin chains; the function inhibits CD4 T-cell activation. Acts as a regulator of retrograde transport: together with MAGEL2, mediates the formation of 'Lys-63'-linked polyubiquitin chains at 'Lys-220' of WASHC1, leading to promote endosomal F-actin assembly (PubMed:23452853). Has a transcriptional repressor activity by cooperating with EPC1. Induces apoptosis by activating Jun N-terminal kinase and p38 kinase and also increases caspase-3-like activity independently of mitochondrial events. May function in male germ cell development. Has DNA-binding activity and preferentially bound to double-stranded DNA. Forms a complex with and ubiquitinates the ubiquitin-specific protease USP7, which in turn deubiquitinates RIPK1 resulting in the positive regulation of TNF-induced apoptosis (PubMed:24144979). In addition, acts with USP7 or PTPN11 as an inhibitor of the antiviral signaling pathway by promoting kinase TBK1 ubiquitination and degradation (PubMed:26358190, PubMed:29688809). Acts as a negative regulator of NOD2 signaling by mediating ubiquitination of NOD2, promoting its degradation by the proteasome (PubMed:22829933). Alternatively, facilitates mitophagy via stabilization of active TBK1 (PubMed:36111389). Negatively regulates autophagy flux under basal conditions by directly polyubiquitinating ULK1 (PubMed:35670107). During starvation-induced autophagy, catalyzes non-degradative ubiquitination of the kinase STK38L promoting its activation and phosphorylation of ULK1 leading to its ubiquitination and degradation to restrain the amplitude and duration of autophagy (PubMed:35670107)\n(Microbial infection) Positively regulates hepatitis C virus replication by suppressing type I IFN response during infection","source":"project UniProt records20261017/18"},{"partner":"YWHAE","hgnc":"HGNC:12851","core":true,"core_annotation":{"hgnc":"HGNC:12851","symbol_at_source":"YWHAE","accession":"P62258","function":"Histone modification erase cofactor","target":"histone","pmids":["10869435"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"broad_context","specificity_weight":0.25,"specificity_note":"多功能信号/泛素/伴侣/骨架背景；该成员在EpiFactors中的作用仍保留，不能单独保证染色质候选优先"},"specificity_weight":0.25,"degree9903":833,"hub_weight":0.23796037813647444,"quality":1,"programmes":["pubmed:16260042"],"pmids":["16260042"],"assays":["reconstituted"],"contexts":[],"partner_location":"Nucleus; Cytoplasm; Melanosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Adapter protein implicated in the regulation of a large spectrum of both general and specialized signaling pathways (PubMed:21189250). Binds to a large number of partners, usually by recognition of a phosphoserine or phosphothreonine motif (PubMed:35343654). Binding generally results in the modulation of the activity of the binding partner (By similarity). Positively regulates phosphorylated protein HSF1 nuclear export to the cytoplasm (PubMed:12917326). Plays a positive role in the antiviral signaling pathway upstream of TBK1 via interaction with RIGI (PubMed:37555661). Mechanistically, directs RIGI redistribution from the cytosol to mitochondrial associated membranes where it mediates MAVS-dependent innate immune signaling during viral infection (PubMed:22607805). Plays a role in proliferation inhibition and cell cycle arrest by exporting HNRNPC from the nucleus to the cytoplasm to be degraded by ubiquitination (PubMed:37599448)","source":"project UniProt records20261017/18"},{"partner":"DMAP1","hgnc":"HGNC:18291","core":true,"core_annotation":{"hgnc":"HGNC:18291","symbol_at_source":"DMAP1","accession":"Q9NPF5","function":"Chromatin remodeling","target":"chromatin","pmids":["14966270"],"complexes":"NuA4, NuA4-related complex, SRCAP","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":162,"hub_weight":0.4856429311786321,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Cytoplasm","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Involved in transcription repression and activation. Its interaction with HDAC2 may provide a mechanism for histone deacetylation in heterochromatin following replication of DNA at late firing origins. Can also repress transcription independently of histone deacetylase activity. May specifically potentiate DAXX-mediated repression of glucocorticoid receptor-dependent transcription. Component of the NuA4 histone acetyltransferase (HAT) complex which is involved in transcriptional activation of select genes principally by acetylation of nucleosomal histones H4 and H2A. This modification may both alter nucleosome - DNA interactions and promote interaction of the modified histones with other proteins which positively regulate transcription. This complex may be required for the activation of transcriptional programs associated with oncogene and proto-oncogene mediated growth induction, tumor suppressor mediated growth arrest and replicative senescence, apoptosis, and DNA repair. NuA4 may also play a direct role in DNA repair when recruited to sites of DNA damage. Participates in the nuclear localization of URI1 and increases its transcriptional corepressor activity","source":"project UniProt records20261017/18"},{"partner":"L3MBTL3","hgnc":"HGNC:23035","core":true,"core_annotation":{"hgnc":"HGNC:23035","symbol_at_source":"L3MBTL3","accession":"Q96JM7","function":"Histone modification read","target":"histone","pmids":["23292653"],"complexes":"#","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":112,"hub_weight":0.5555555555555556,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Is a negative regulator of Notch target genes expression, required for RBPJ-mediated transcriptional repression (PubMed:29030483). It recruits KDM1A to Notch-responsive elements and promotes KDM1A-mediated H3K4me demethylation (PubMed:29030483). Involved in the regulation of ubiquitin-dependent degradation of a set of methylated non-histone proteins, including SOX2, DNMT1 and E2F1. It acts as an adapter recruiting the CRL4-DCAF5 E3 ubiquitin ligase complex to methylated target proteins (PubMed:29691401, PubMed:30442713). Required for normal maturation of myeloid progenitor cells (By similarity)","source":"project UniProt records20261017/18"}],"near_known_relatives":[]},"ZMAT1":{"coreEvidence":[{"partner":"H2AX","hgnc":"HGNC:4739","core":true,"core_annotation":{"hgnc":"HGNC:4739","symbol_at_source":"H2AFX","accession":"P16104","function":"Histone/protamine","target":"chromatin","pmids":[],"version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":507,"hub_weight":0.29961075885598987,"quality":0.65,"programmes":["BioPlex"],"pmids":["33961781"],"assays":["capture_association"],"contexts":["IntAct_host:[\"Homo sapiens HEK293T embryonic kidney cell\", \"human-293t\"]","dataset_cell:HEK293T"],"partner_location":"Nucleus; Chromosome","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Variant histone H2A which replaces conventional H2A in a subset of nucleosomes. Nucleosomes wrap and compact DNA into chromatin, limiting DNA accessibility to the cellular machineries which require DNA as a template. Histones thereby play a central role in transcription regulation, DNA repair, DNA replication and chromosomal stability. DNA accessibility is regulated via a complex set of post-translational modifications of histones, also called histone code, and nucleosome remodeling. Required for checkpoint-mediated arrest of cell cycle progression in response to low doses of ionizing radiation and for efficient repair of DNA double strand breaks (DSBs) specifically when modified by C-terminal phosphorylation","source":"project UniProt records20261017/18"},{"partner":"OIP5","hgnc":"HGNC:20300","core":true,"core_annotation":{"hgnc":"HGNC:20300","symbol_at_source":"OIP5","accession":"O43482","function":"Chromatin remodeling","target":"histone","pmids":["17199038"],"complexes":"Mis18","version":"EpiFactors2.1","source":"https://epifactors.autosome.org/description","specificity_class":"chromatin_reference","specificity_weight":1,"specificity_note":"本版策展染色质参照；也不等于该蛋白只在染色质起作用"},"specificity_weight":1,"degree9903":152,"hub_weight":0.4975185951049946,"quality":0.75,"programmes":["CCSB_binary_maps"],"pmids":["32296183"],"assays":["binary_reporter"],"contexts":[],"partner_location":"Nucleus; Chromosome; Chromosome, centromere","partner_has_nuclear_annotation":true,"partner_location_assessed":true,"function":"Required for recruitment of CENPA to centromeres and normal chromosome segregation during mitosis","source":"project UniProt records20261017/18"}],"near_known_relatives":[]}};
